    if (gpiod_line_request_output(line1, "digital-out", 0) < 0) {
        perror("gpiod_line_request_output(pin 2)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital-out", 0) < 0) {
        perror("gpiod_line_request_output(pin 3)");
