        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, val1, GPIO_PIN_2, val2);
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
