    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("Exiting cleanly.\n");

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define CONSUMER "digital_output"

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    while (keep_running) {
        /* Set both lines to the same state */
        int state = 0;
        if (gpiod_line_set_value(line1, state) < 0) {
            perror("gpiod_line_set_value(line1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, state) < 0) {
            perror("gpiod_line_set_value(line2)");
            goto cleanup;
        }

        printf("GPIO 2: %d, GPIO 3: %d\n", state, state);
        fflush(stdout);

        usleep(100000); /* 0.1 seconds */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 2
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Request the line as output, initial value 0 */
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Main loop */
    while (keep_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_LINE, strerror(errno));
            goto cleanup;
        }

        if (value == 0 || value == 1) {
            printf("GPIO %d: %d\n", GPIO_LINE, value);
            fflush(stdout);
        } else {
            fprintf(stderr, "Invalid value %d on GPIO %d\n", value, GPIO_LINE);
            goto cleanup;
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release the line and close the chip on all exit paths */
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_0_0 (0x04 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (0x01 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x04 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)

static int i2c_fd = -1;

static int i2c_write_reg(uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(i2c_fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg error: %s\n", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int init_ads1115(void) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_0_0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    if (i2c_write_reg(ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }
    usleep(10000);
    return 0;
}

static int read_ads1115(int16_t *value) {
    uint16_t raw;
    if (i2c_read_reg(ADS1115_REG_CONVERSION, &raw) < 0) {
        return -1;
    }
    *value = (int16_t)raw;
    return 0;
}

int main(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_ads1115() < 0) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        int16_t raw;
        if (read_ads1115(&raw) < 0) {
            fprintf(stderr, "Failed to read ADS1115\n");
            break;
        }
        printf("Raw ADC Value: %d\n", raw);
        fflush(stdout);
        usleep(500000);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MLX90614_ADDR 0x5a
#define MLX90614_REG_TEMP 0x00
#define I2C_DEV "/dev/i2c-1"
#define POLL_INTERVAL_SEC 5

static int i2c_fd = -1;

static int i2c_open(void) {
    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_DEV, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MLX90614_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;

    msgs[0].addr = MLX90614_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &reg;

    msgs[1].addr = MLX90614_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 2;
    msgs[1].buf = buf;

    data.msgs = msgs;
    data.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    i2c_fd = i2c_open();
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t raw;
        if (i2c_read_reg16(i2c_fd, MLX90614_REG_TEMP, &raw) < 0) {
            fprintf(stderr, "Failed to read temperature. Exiting.\n");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        printf("Temperature: %u\n", raw);
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

