#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) {
        perror("i2c_write_reg16");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg16 write");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read_reg16 read");
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    int fd = -1;
    struct sigaction sa;
    uint16_t config;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    /*
     * ADS1115 Config Register (0x01):
     * Bit 15: 1 (Operational status / single-shot mode)
     * Bits 14:12: 100 (AIN0 single-ended)
     * Bits 11:9: 000 (Gain = 1x)
     * Bits 8:7: 00 (Data rate = 128 SPS)
     * Bits 6:5: 00 (Comparator disabled)
     * Bit 4: 0 (Traditional comparator)
     * Bits 3:0: 1000 (Continuous conversion)
     * => 0x8400
     */
    config = 0x8400;

    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        close(fd);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw;
        if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &raw) < 0) {
            fprintf(stderr, "Failed to read conversion register\n");
            break;
        }
        printf("Raw ADC Value: %u\n", raw);
        fflush(stdout);
        usleep(100000); /* 100 ms */
    }

    if (fd >= 0) {
        close(fd);
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_17 17
#define GPIO_18 18

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL, *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line17, "digital_output", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line18, "digital_output", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    /* Set the output values */
    if (gpiod_line_set_value(line17, 1) < 0) {
        fprintf(stderr, "Failed to set line %d high: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_set_value(line18, 0) < 0) {
        fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    /* Report the state */
    printf("GPIO 17 HIGH, GPIO 18 LOW\n");
    fflush(stdout);

    /* Wait for the signal to arrive */
    while (running) {
        sleep(1);
    }

    /* Clean shutdown: set outputs to LOW */
    gpiod_line_set_value(line17, 0);
    gpiod_line_set_value(line18, 0);
    ret = EXIT_SUCCESS;

cleanup:
    /* Release the lines and close the chip */
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

