static int wait_for_level(struct gpiod_line *line, int val, uint32_t timeout_us) {
    uint32_t start = gpiod_line_get_value(line);
    if (start < 0) return -1;
    if (start == val) return 0;
    for (uint32_t elapsed = 0; elapsed < timeout_us; elapsed += 10) {
        start = gpiod_line_get_value(line);
        if (start < 0) return -1;
        if (start == val) return 0;
        usleep(10000);
    }
    return -1;
}

static int measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trigger, 0) < 0) return -1;
    usleep(2);
    if (gpiod_line_set_value(trigger, 1) < 0) return -1;
    if (wait_for_level(echo, 0, TIMEOUT_US) < 0) return -1;
    if (wait_for_level(echo, 1, TIMEOUT_US) < 0) return -1;
    uint32_t pulse_start = gpiod_line_get_value(echo);
    if (pulse_start < 0) return -1;
    uint32_t pulse_end = gpiod_line_get_value(echo);
    if (pulse_end < 0) return -1;
    uint32_t pulse_width = pulse_end - pulse_start;
    return (int)(pulse_width * 500000 / 2000000);
}

