        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    /* Main loop: toggle each line once per cycle */
    while (keep_running) {
        /* State 0: line1 LOW, line2 HIGH */
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(line1, 0)");
