#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

static int i2c_fd = -1;

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_ads1115(int fd, uint16_t *raw_value) {
    uint16_t config = 0x8000 | 0x4000 | 0x0100; /* AIN0 single-ended, 4.096V, 128 SPS, start conversion */
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }
    usleep(10000); /* 10 ms conversion wait */
    uint16_t conv;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &conv) < 0) {
        return -1;
    }
    *raw_value = conv;
    return 0;
}

int main(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint16_t raw_value;
    int exit_code = EXIT_SUCCESS;

    for (int i = 0; i < 3; i++) {
        if (read_ads1115(i2c_fd, &raw_value) < 0) {
            fprintf(stderr, "Error reading ADS1115 at iteration %d\n", i + 1);
            exit_code = EXIT_FAILURE;
            break;
        }
        printf("Iteration %d: raw value = %u\n", i + 1, raw_value);
        sleep(1);
    }

    if (close(i2c_fd) < 0) {
        fprintf(stderr, "Failed to close I2C device: %s\n", strerror(errno));
        exit_code = EXIT_FAILURE;
    }

    return exit_code;
}

