#include <string.h>
#include <gpiod.h>

#define HC_SR04_TRIGGER 17
#define HC_SR04_ECHO    18
#define CHIP_NAME       "gpiochip4"
#define TIMEOUT_US      30000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static int wait_for_level(struct gpiod_line *line, int val, uint32_t timeout_us) {
    uint32_t start = (uint32_t)clock();
    while (1) {
        int v = gpiod_line_get_value(line);
        if (v < 0) {
            return -1;
        }
        if (v == val) return 0;
        if ((uint32_t)(clock() - start) >= timeout_us) return -2;
    }
}

static int trigger_and_measure(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(2);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;

    return wait_for_level(echo, 0, TIMEOUT_US);
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    int ret = trigger_and_measure(trig, echo);
    if (ret < 0) return -1;

    ret = wait_for_level(echo, 1, TIMEOUT_US);
    if (ret < 0) return -1;

    uint32_t start = (uint32_t)clock();
    ret = wait_for_level(echo, 0, TIMEOUT_US);
    if (ret < 0) return -1;

    uint32_t elapsed = (uint32_t)(clock() - start);
    return (int)(elapsed * 300000000.0 / 2000000000.0);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, HC_SR04_TRIGGER);
    echo = gpiod_chip_get_line(chip, HC_SR04_ECHO);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int dist = measure_distance(trig, echo);
        if (dist < 0) {
            fprintf(stderr, "Error: HC-SR04 not responding or out of range.\n");
            goto cleanup;
        }
        printf("Distance: %d cm\n", dist);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

