#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define NUM_CYCLES 3

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line1, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_PIN_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit after %d cycles.\n", NUM_CYCLES);

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        /* Set both lines to 1 */
        if (gpiod_line_set_value(line1, 1) < 0) {
