#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define DHT11_TIMEOUT_US 200

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_line(struct gpiod_line *line, int val, int timeout_us) {
    for (int i = 0; i < timeout_us; i++) {
        if (gpiod_line_get_value(line) == val) return 0;
        usleep(1);
    }
    return -1;
}

static int read_dht11(struct gpiod_line *line, int *out_data) {
    int data[5] = {0, 0, 0, 0, 0};
    int i;

    /* Send start signal: pull low for >=1ms, then high for 20-40us */
    if (gpiod_line_request_output(line, "dht11", 0) < 0) return -1;
    if (gpiod_line_set_value(line, 0) < 0) return -1;
    usleep(2000);
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);
    if (gpiod_line_set_value(line, 0) < 0) return -1;

    /* Switch to input; DHT11 pulls low while reading */
    if (gpiod_line_request_input(line, "dht11") < 0) return -1;

    /* Wait for sensor response: low then high */
    if (wait_for_line(line, 0, DHT11_TIMEOUT_US) < 0) return -1;
    if (wait_for_line(line, 1, DHT11_TIMEOUT_US) < 0) return -1;

    /* Read 40 bits */
    for (i = 0; i < 40; i++) {
        /* Wait for low-to-high transition (end of low pulse) */
        if (wait_for_line(line, 0, DHT11_TIMEOUT_US) < 0) return -1;
        /* Measure high pulse width: 26us = '0', 70us = '1' */
        int high_us = 0;
        if (wait_for_line(line, 1, DHT11_TIMEOUT_US) < 0) return -1;
        high_us = 0;  /* timeout */
        if (wait_for_line(line, 0, DHT11_TIMEOUT_US) < 0) return -1;

        data[i / 8] <<= 1;
        if (high_us > 40) data[i / 8] |= 1;
    }

    /* Verify checksum */
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) return -1;

    *out_data = (data[0] << 4) | (data[1] << 2) | data[2];
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT11_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line, "dht11") < 0) {
        fprintf(stderr, "Failed to request input on GPIO %d: %s\n", DHT11_PIN, strerror(errno));
        goto cleanup;
    }

    printf("DHT11 on GPIO %d (BCM). Press Ctrl+C to exit.\n", DHT11_PIN);

    while (running) {
        int d = read_dht11(line, &data[0]);
        if (d == 0) {
            printf("DHT11: %d\n", data[0]);
            fflush(stdout);
        } else if (d < 0) {
            fprintf(stderr, "DHT11 read error: %s\n", strerror(errno));
        } else {
