#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define OPT3001_ADDR 0x44
#define I2C_DEV "/dev/i2c-1"

static int i2c_fd = -1;

static int i2c_init(void) {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEV, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", OPT3001_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_opt3001(uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t cmd[2] = {0x80, 0x80};
    uint8_t buf[6];

    if (write(i2c_fd, cmd, 2) != 2) {
        fprintf(stderr, "Error writing to OPT3001: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);

    if (read(i2c_fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading from OPT3001: %s\n", strerror(errno));
        return -1;
    }

    *red = (buf[0] << 8) | buf[1];
    *green = (buf[2] << 8) | buf[3];
    *blue = (buf[4] << 8) | buf[5];

    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    if (i2c_init() != 0) {
        return EXIT_FAILURE;
    }

    uint16_t red, green, blue;

    if (read_opt3001(&red, &green, &blue) == 0) {
        printf("Red: %u, Green: %u, Blue: %u\n", red, green, blue);
    } else {
        fprintf(stderr, "Failed to read OPT3001 data.\n");
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define POLL_INTERVAL_US 500000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void cleanup_and_exit(int signum) {
    (void)signum;
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_LINE, val);
        fflush(stdout);
        usleep(POLL_INTERVAL_US);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

