#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 2
#define VALID_VALUES {0, 1}
#define NUM_CYCLES 3
#define CYCLE_DELAY_SEC 60

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value 0 */
    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Digital output control started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_LINE);

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        int value = (i % 2 == 0) ? 1 : 0; /* Cycle through 0 and 1 */

        if (gpiod_line_set_value(line, value) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO %d: %d\n", GPIO_LINE, value);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < CYCLE_DELAY_SEC && keep_running; s++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure the line is left in a safe state (low) on exit */
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Exiting cleanly.\n");
    }
    return ret;
}

