#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define OW_PIN_1 4
#define OW_PIN_2 17
#define OW_PIN_3 18
#define NUM_PINS 3
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int pins[NUM_PINS], int *out_temp) {
    char filename[64];
    snprintf(filename, sizeof(filename), "/sys/bus/w1/devices/28-000000000000/w1_slave");

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        FILE *fp = fopen(filename, "r");
        if (fp == NULL) {
            fprintf(stderr, "Error: Failed to open %s (attempt %d): %s\n",
                    filename, attempt + 1, strerror(errno));
            sleep(1);
            continue;
        }

        char line[256];
        if (fgets(line, sizeof(line), fp) == NULL) {
            fprintf(stderr, "Error: Failed to read from %s (attempt %d): %s\n",
                    filename, attempt + 1, strerror(errno));
            fclose(fp);
            sleep(1);
            continue;
        }
        fclose(fp);

        if (strstr(line, "YES") == NULL) {
            fprintf(stderr, "Error: No valid data from %s (attempt %d)\n",
                    filename, attempt + 1);
            sleep(1);
            continue;
        }

        char *temp_str = strstr(line, "t=");
        if (temp_str == NULL) {
            fprintf(stderr, "Error: Temperature data not found in %s (attempt %d)\n",
                    filename, attempt + 1);
            sleep(1);
            continue;
        }

        long raw = strtol(temp_str + 2, NULL, 10);
        *out_temp = (int)(raw / 1000);
        return 0;
    }

    fprintf(stderr, "Error: Failed to read temperature after %d attempts\n", MAX_RETRIES);
    return -1;
}

int main(void) {
    int pins[NUM_PINS] = {OW_PIN_1, OW_PIN_2, OW_PIN_3};
    int valid_pins[NUM_PINS] = {OW_PIN_1, OW_PIN_2, OW_PIN_3};
    int num_valid = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    printf("DS18B20 temperature reader started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (valid_pins[i] == 0) {
                continue;
            }

            if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
                fprintf(stderr, "Error: Failed to set GPIO %d as output: %s\n",
                        pins[i], strerror(errno));
                continue;
            }

            if (gpioWrite(pins[i], 0) < 0) {
                fprintf(stderr, "Error: Failed to pull low on GPIO %d: %s\n",
                        pins[i], strerror(errno));
                gpioSetMode(pins[i], PI_INPUT);
                continue;
            }

            usleep(10000);

            if (gpioSetMode(pins[i], PI_INPUT) < 0) {
                fprintf(stderr, "Error: Failed to set GPIO %d as input: %s\n",
                        pins[i], strerror(errno));
                gpioWrite(pins[i], 1);
                continue;
            }

            usleep(10000);

            if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
                fprintf(stderr, "Error: Failed to set GPIO %d as output: %s\n",
                        pins[i], strerror(errno));
                gpioWrite(pins[i], 1);
                continue;
            }

            if (gpioWrite(pins[i], 1) < 0) {
                fprintf(stderr, "Error: Failed to pull high on GPIO %d: %s\n",
                        pins[i], strerror(errno));
                gpioSetMode(pins[i], PI_INPUT);
                continue;
            }

            usleep(10000);

            if (gpioSetMode(pins[i], PI_INPUT) < 0) {
                fprintf(stderr, "Error: Failed to set GPIO %d as input: %s\n",
                        pins[i], strerror(errno));
                gpioWrite(pins[i], 0);
                continue;
            }

            if (read_temperature(pins, &(*out_temp)) == 0) {
                printf("Temperature on GPIO %d: %d C\n", pins[i], *out_temp);
                num_valid++;
            } else {
                fprintf(stderr, "Warning: Failed to read temperature on GPIO %d\n", pins[i]);
            }
        }

        if (num_valid > 0) {
            printf("Valid readings: %d\n", num_valid);
        } else {
            printf("No valid readings this cycle.\n");
        }

        for (int i = 0; i < NUM_PINS; i++) {
            if (gpioSetMode(pins[i], PI_INPUT) < 0) {
                fprintf(stderr, "Error: Failed to set GPIO %d back to input: %s\n",
                        pins[i], strerror(errno));
            }
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

