#define HTU21D_RESET 0x04

static int i2c_fd = -1;

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int htu21d_init(int fd) {
    if (i2c_write_byte(fd, HTU21D_RESET, 0x01) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, HTU21D_MEAS_CONF, 0x00) < 0) return -1;
    return 0;
}

static int htu21d_read_temperature(int fd, float *temperature) {
    uint8_t temp_msb, temp_lsb;
    if (i2c_read_byte(fd, HTU21D_TEMP_MSB, &temp_msb) < 0) return -1;
    if (i2c_read_byte(fd, HTU21D_TEMP_LSB, &temp_lsb) < 0) return -1;
    int16_t raw = (int16_t)((temp_msb << 8) | temp_lsb);
    *temperature = (float)raw / 16.0;
    return 0;
}

static int htu21d_read_pressure(int fd, float *pressure) {
    uint8_t press_msb, press_lsb;
    if (i2c_read_byte(fd, HTU21D_PRESS_MSB, &press_msb) < 0) return -1;
    if (i2c_read_byte(fd, HTU21D_PRESS_LSB, &press_lsb) < 0) return -1;
    int32_t raw = (int32_t)((press_msb << 8) | press_lsb);
    *pressure = (float)raw / 16.0;
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (htu21d_init(i2c_fd) < 0) {
        fprintf(stderr, "HTU21D initialization failed (device may be absent)\n");
        cleanup();
        return 1;
    }

    while (1) {
        float temperature, pressure;
        if (htu21d_read_temperature(i2c_fd, &temperature) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
        } else if (htu21d_read_pressure(i2c_fd, &pressure) < 0) {
            fprintf(stderr, "Failed to read pressure\n");
        } else {
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
        }
        sleep(60);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN_1 4
#define GPIO_PIN_2 18
#define POLL_INTERVAL_US 50000  /* 0.05 seconds */

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line(GPIO_PIN_1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line1, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (keep_running) {
        /* Set both lines to the current state */
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(line1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(line2)");
            goto cleanup;
        }

        printf("State: 0\n");
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_1 2
#define GPIO_2 3
#define POLL_INTERVAL_SEC 2

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two GPIO lines */
    line1 = gpiod_chip_get_line(chip, GPIO_1);
    if (!line1) {
        perror("gpiod_chip_get_line(GPIO_1)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line1, "digital-out", 0) < 0) {
        perror("gpiod_line_request_output(GPIO_1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "digital-out", 0) < 0) {
        perror("gpiod_line_request_output(GPIO_2)");
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Set both lines to the same value */
        if (gpiod_line_set_value(line1, gpiod_line_get_value(line2)) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        /* Print the state of the first line */
        int val1 = gpiod_line_get_value(line1);
        if (val1 < 0) {
            perror("gpiod_line_get_value(GPIO_1)");
            goto cleanup;
        }
        printf("GPIO %d: %d\n", GPIO_1, val1);
        fflush(stdout);

        /* Sleep for the poll interval, but wake early on signal */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_BW_RATE 0x2C

static int i2c_fd = -1;

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting I2C reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading from I2C reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    if (i2c_write_byte(fd, ADXL345_POWER_CTL, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, ADXL345_DATA_FORMAT, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, ADXL345_BW_RATE, 0x0A) < 0) return -1;
    if (i2c_write_byte(fd, ADXL345_POWER_CTL, 0x08) < 0) return -1;
    return 0;
}

static int read_adxl345(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, ADXL345_DATAX0, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

int main(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }
    while (1) {
        int16_t x, y, z;
        if (read_adxl345(i2c_fd, &x, &y, &z) == 0) {
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read ADXL345 data\n");
        }
        sleep(0.1);
    }
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 27
#define CYCLES 50
#define DELAY_US 100000  /* 0.1 seconds */

static volatile sig_atomic_t keep_running = 1;

static void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean exit */
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output on GPIO %d (BCM) running. Press Ctrl+C to exit after %d cycles.\n",
           GPIO_LINE, CYCLES);

    for (int i = 0; i < CYCLES && keep_running; i++) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (HIGH)");
            break;
        }
        printf("GPIO %d HIGH\n", GPIO_LINE);
        usleep(DELAY_US);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (LOW)");
            break;
        }
        printf("GPIO %d LOW\n", GPIO_LINE);
        usleep(DELAY_US);
    }

    /* Clean up: set line LOW and release */
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

