#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define DHT22_PIN_1 17
#define DHT22_PIN_2 22
#define DHT22_PIN_3 23
#define DHT22_PIN_4 24

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_line(struct gpiod_line *line, int val, int timeout_ms) {
    for (int i = 0; i < timeout_ms; i++) {
        if (gpiod_line_get_value(line) == val) return 0;
        usleep(1000);
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line1, struct gpiod_line *line2, struct gpiod_line *line3, struct gpiod_line *line4, int *out_data) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int bit = 0;
    int last_state = 1;

    gpiod_line_set_config(line1, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, 0);
    gpiod_line_set_config(line2, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, 0);
    gpiod_line_set_config(line3, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, 0);
    gpiod_line_set_config(line4, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, 0);

    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_set_value(line3, 0);
    gpiod_line_set_value(line4, 0);

    usleep(20000);
    gpiod_line_set_value(line1, 1);
    usleep(40);
    gpiod_line_set_value(line1, 0);

    gpiod_line_set_value(line2, 1);
    usleep(40);
    gpiod_line_set_value(line2, 0);

    gpiod_line_set_value(line3, 1);
    usleep(80);
    gpiod_line_set_value(line3, 0);

    gpiod_line_set_value(line4, 1);
    usleep(80);
    gpiod_line_set_value(line4, 0);

    if (wait_for_line(line1, 0, 100) < 0) return -1;
    if (wait_for_line(line2, 1, 100) < 0) return -1;
    if (wait_for_line(line3, 0, 100) < 0) return -1;
    if (wait_for_line(line4, 1, 100) < 0) return -1;

    for (bit = 0; bit < 40; bit++) {
        if (wait_for_line(line1, 1, 100) < 0) return -1;
        if (wait_for_line(line2, 0, 100) < 0) return -1;
        if (wait_for_line(line3, 1, 100) < 0) return -1;
        if (wait_for_line(line4, 0, 100) < 0) return -1;

        int count = 0;
        while (gpiod_line_get_value(line1) == 1 && count < 100) {
            usleep(1000);
            count++;
        }
        data[bit_idx] <<= 1;
        if (count > 10) data[bit_idx] |= 1;
        bit_idx++;
    }

    if (wait_for_line(line1, 1, 100) < 0) return -1;
    if (wait_for_line(line2, 0, 100) < 0) return -1;
    if (wait_for_line(line3, 1, 100) < 0) return -1;
    if (wait_for_line(line4, 0, 100) < 0) return -1;

    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        return -2;
    }

    *out_data = (data[0] << 8) | data[1];
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL, *line4 = NULL;
