#include <string.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_PDATA 0x1A

static int i2c_fd = -1;

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_byte(fd, TCS34725_ID, &id) < 0) {
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Error: Invalid TCS34725 ID: 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write_byte(fd, TCS34725_ATIME, 0x03) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_CONTROL, 0x01) < 0) return -1;
    return 0;
}

static int tcs34725_read_data(int fd, uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t cdata, rdata, gdata, pdata;
    if (i2c_read_byte(fd, TCS34725_CDATA, &cdata) < 0) return -1;
    if (i2c_read_byte(fd, TCS34725_RDATA, &rdata) < 0) return -1;
    if (i2c_read_byte(fd, TCS34725_GDATA, &gdat) < 0) return -1;
    if (i2c_read_byte(fd, TCS34725_PDATA, &pdata) < 0) return -1;
    *r = (uint16_t)rdata;
    *g = (uint16_t)gdat;
    *b = (uint16_t)pdata;
    return 0;
}

int main(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing TCS34725\n");
        close(i2c_fd);
        return 1;
    }
    while (1) {
        uint16_t r, g, b;
        if (tcs34725_read_data(i2c_fd, &r, &g, &b) == 0) {
            printf("R: %u, G: %u, B: %u\n", r, g, b);
        } else {
            fprintf(stderr, "Error reading data from TCS34725\n");
        }
        usleep(200000);
    }
    close(i2c_fd);
    return 0;
}

