#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set PWM pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioPWM(PWM_PIN_1, 1) != 0 ||
            gpioPWM(PWM_PIN_2, 1) != 0 ||
            gpioPWM(PWM_PIN_3, 1) != 0 ||
            gpioPWM(PWM_PIN_4, 1) != 0) {
            fprintf(stderr, "Failed to set PWM on one or more pins\n");
            break;
        }
        printf("PWM: GPIO %d, GPIO %d, GPIO %d, GPIO %d ON\n",
               PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4);
        fflush(stdout);
        gpioDelay(1000000);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    23
#define ECHO_PIN2   24

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo1 = NULL, *echo2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo1 = gpiod_chip_get_line(chip, ECHO_PIN);
    echo2 = gpiod_chip_get_line(chip, ECHO_PIN2);
    if (!trig || !echo1 || !echo2) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_output(echo1, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output(echo1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(echo2, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output(echo2)");
        goto cleanup;
    }

    printf("HC-SR04 ready. Press Ctrl+C to exit.\n");

    while (running) {
        gpiod_line_set_value(trig, 0);
        usleep(2);
        gpiod_line_set_value(trig, 1);
        usleep(10);
        gpiod_line_set_value(trig, 0);

        int start_tick = gpiod_line_get_value(echo1);
        int end_tick = gpiod_line_get_value(echo2);

        if (start_tick < 0 || end_tick < 0) {
            fprintf(stderr, "Error reading echo pin.\n");
