#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_PIN 18
#define NUM_PIXELS 100
#define DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    int colours[NUM_PIXELS][3] = {
        {255, 0, 0}, {0, 255, 0}, {0, 0, 255}, {255, 255, 0},
        {255, 0, 255}, {0, 255, 255}, {128, 128, 128}, {128, 0, 0},
        {128, 128, 0}, {128, 0, 128}
    };

    while (running) {
        for (int i = 0; i < NUM_PIXELS; i++) {
            if (gpioWrite(GPIO_PIN, colours[i][0]) != 0) {
                fprintf(stderr, "Error: failed to write to GPIO %d\n", GPIO_PIN);
                running = 0;
                break;
            }
            if (gpioWrite(GPIO_PIN + 1, colours[i][1]) != 0) {
                fprintf(stderr, "Error: failed to write to GPIO %d\n", GPIO_PIN + 1);
                running = 0;
                break;
            }
            if (gpioWrite(GPIO_PIN + 2, colours[i][2]) != 0) {
                fprintf(stderr, "Error: failed to write to GPIO %d\n", GPIO_PIN + 2);
                running = 0;
                break;
            }
        }
        gpioDelay(DELAY_US);
    }

    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

