    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define HD44780_ADDR 0x27
#define HD44780_RW 0x00
#define HD44780_EN 0x04
#define HD44780_RS 0x01
#define HD44780_DATA_0 0x08
#define HD44780_DATA_1 0x09
#define HD44780_FUNCTION 0x00
#define HD44780_DISPLAY_ON 0x03
#define HD44780_DISPLAY_OFF 0x02
#define HD44780_CURSOR_UP 0x01
#define HD44780_CURSOR_DOWN 0x02
#define HD44780_CURSOR_LEFT 0x04
#define HD44780_CURSOR_RIGHT 0x06
#define HD44780_ENTRY_MODE 0x00
#define HD44780_CLEAR 0x07
#define HD44780_SET_DDRAM 0x80

static int i2c_fd = -1;

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static int i2c_write_byte(int fd, unsigned char byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int hd44780_send_command(int fd, unsigned char cmd) {
    unsigned char args[2] = {HD44780_FUNCTION, cmd};
    if (i2c_write_byte(fd, args[0]) < 0) return -1;
    if (i2c_write_byte(fd, args[1]) < 0) return -1;
    return 0;
}

static int hd44780_send_data(int fd, unsigned char data) {
    unsigned char args[2] = {HD44780_DATA_0, data};
    if (i2c_write_byte(fd, args[0]) < 0) return -1;
    if (i2c_write_byte(fd, args[1]) < 0) return -1;
    return 0;
}

static int hd44780_init(int fd) {
    if (hd44780_send_command(fd, HD44780_DISPLAY_ON) < 0) return -1;
    if (hd44780_send_command(fd, HD44780_FUNCTION) < 0) return -1;
    if (hd44780_send_command(fd, HD44780_DISPLAY_ON) < 0) return -1;
    if (hd44780_send_command(fd, HD44780_ENTRY_MODE) < 0) return -1;
    if (hd44780_send_command(fd, HD44780_CLEAR) < 0) return -1;
    if (hd44780_send_command(fd, HD44780_DISPLAY_ON) < 0) return -1;
    if (hd44780_send_command(fd, HD44780_SET_DDRAM) < 0) return -1;
    if (hd44780_send_command(fd, HD44780_DISPLAY_OFF) < 0) return -1;
    if (hd44780_send_command(fd, HD44780_DISPLAY_ON) < 0) return -1;
    return 0;
}

static int hd44780_write_string(int fd, const char *str) {
    while (*str) {
        if (hd44780_send_data(fd, (unsigned char)*str) < 0) return -1;
        str++;
    }
    return 0;
}

int main(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HD44780_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HD44780_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (hd44780_init(i2c_fd) < 0) {
        fprintf(stderr, "HD44780 initialization failed\n");
        cleanup();
        return 1;
    }

    while (1) {
        if (hd44780_write_string(i2c_fd, "Hello, World!") < 0) {
            fprintf(stderr, "Failed to write to HD44780\n");
            cleanup();
            return 1;
        }
        sleep(10);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define I2C_BUS "/dev/i2c-1"

int main(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Wake up the MPU6050 (clear sleep bit)
    if (ioctl(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error waking up MPU6050: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Allow time for the sensor to stabilize
    usleep(100000);

    for (int i = 0; i < 100; i++) {
        uint8_t reg = MPU6050_ACCEL_XOUT_H;
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        uint8_t buf[6];
        if (read(fd, buf, 6) != 6) {
            fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        int16_t x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Reading %d: X=%d, Y=%d, Z=%d\n", i, x, y, z);
        usleep(10000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_14 14
#define GPIO_15 15
#define CONSUMER "digital_output"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line14 = NULL;
    struct gpiod_line *line15 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    line14 = gpiod_chip_get_line(chip, GPIO_14);
    if (!line14) {
        perror("gpiod_chip_get_line(14)");
        goto cleanup;
    }

    line15 = gpiod_chip_get_line(chip, GPIO_15);
    if (!line15) {
        perror("gpiod_chip_get_line(15)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line14, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(14)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line15, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(15)");
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (keep_running) {
        int val14 = gpiod_line_get_value(line14);
        int val15 = gpiod_line_get_value(line15);

        if (val14 < 0 || val15 < 0) {
            fprintf(stderr, "Error reading GPIO lines (14=%d, 15=%d): %s\n",
                    val14, val15, strerror(errno));
            goto cleanup;
        }

        if (val14 != 0 || val15 != 0) {
            printf("GPIO 14: %d, GPIO 15: %d\n", val14, val15);
            fflush(stdout);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line14) {
        gpiod_line_release(line14);
    }
    if (line15) {
        gpiod_line_release(line15);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Exiting cleanly.\n");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#include <mqtt/mqtt.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "sensor/readings"
#define READ_INTERVAL_SEC 0.01

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int publish_reading(const char *topic, const char *payload) {
    int rc = mqtt_connect_async(NULL, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (rc != MQTT_SUCCESS) {
        fprintf(stderr, "MQTT connect failed: %s\n", mqtt_strerror(rc));
        return -1;
    }

    rc = mqtt_subscribe_async(NULL, topic, 1);
    if (rc != MQTT_SUCCESS) {
        fprintf(stderr, "MQTT subscribe failed: %s\n", mqtt_strerror(rc));
        mqtt_disconnect(NULL, 1000);
        return -1;
    }

    rc = mqtt_publish_async(NULL, topic, (int)strlen(payload), payload, 0, NULL);
    if (rc != MQTT_SUCCESS) {
        fprintf(stderr, "MQTT publish failed: %s\n", mqtt_strerror(rc));
        mqtt_unsubscribe_async(NULL, topic, 1);
        mqtt_disconnect(NULL, 1000);
        return -1;
    }

    return 0;
}

static int validate_reading(const char *reading) {
    if (reading == NULL || reading[0] == '\0') {
        return -1;
    }
    if (strlen(reading) < 10) {
        fprintf(stderr, "Reading too short: %s\n", reading);
        return -1;
    }
    if (reading[0] != '0' && reading[0] != '1' && reading[0] != '2' &&
        reading[0] != '3' && reading[0] != '4' && reading[0] != '5' &&
        reading[0] != '6' && reading[0] != '7' && reading[0] != '8' &&
        reading[0] != '9' && reading[0] != 'A' && reading[0] != 'B' &&
        reading[0] != 'C' && reading[0] != 'D' && reading[0] != 'E' &&
        reading[0] != 'F' && reading[0] != 'G' && reading[0] != 'H' &&
        reading[0] != 'I' && reading[0] != 'J' && reading[0] != 'K' &&
        reading[0] != 'L' && reading[0] != 'M' && reading[0] != 'N' &&
        reading[0] != 'O' && reading[0] != 'P' && reading[0] != 'Q' &&
        reading[0] != 'R' && reading[0] != 'S' && reading[0] != 'T' &&
        reading[0] != 'U' && reading[0] != 'V' && reading[0] != 'W' &&
        reading[0] != 'X' && reading[0] != 'Y' && reading[0] != 'Z') {
        fprintf(stderr, "Invalid character in reading: %s\n", reading);
        return -1;
    }
    if (reading[strlen(reading) - 1] != '\0') {
        fprintf(stderr, "Reading ends with null: %s\n", reading);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    MQTTClient client;
    memset(&client, 0, sizeof(client));
    client.on_connect = NULL;
    client.on_disconnect = NULL;
    client.on_message = NULL;
    client.on_error = NULL;
    client.on_publish = NULL;

    if (mqtt_create(&client, NULL) != MQTT_SUCCESS) {
        fprintf(stderr, "MQTT client creation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (publish_reading(MQTT_TOPIC, "0000000000000000") != 0) {
        fprintf(stderr, "Initial publish failed\n");
        mqtt_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        char reading[16];
        snprintf(reading, sizeof(reading), "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz");

        if (validate_reading(reading) == 0) {
            if (publish_reading(MQTT_TOPIC, reading) != 0) {
                fprintf(stderr, "Publish failed\n");
            }
        } else {
            fprintf(stderr, "Invalid reading, giving up\n");
        }

        time_sleep(READ_INTERVAL_SEC);
    }

    mqtt_disconnect(NULL, 1000);
    mqtt_destroy(&client);
    gpioTerminate();
    return EXIT_SUCCESS;
}

