#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    22
#define ALARM_PIN   27

#define TIMEOUT_US  2000000
#define POLL_US     10000
#define LOOP_US     100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int val, uint32_t timeout_us)
{
    uint32_t start = gpiod_line_get_value(line);
    if (start < 0) {
        fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
        return -1;
    }
    uint32_t elapsed = 0;
    while (elapsed < timeout_us) {
        start = gpiod_line_get_value(line);
        if (start < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (start == val)
            return 0;
        usleep(POLL_US);
        elapsed += POLL_US;
    }
    return -1;
}

static int measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo, struct gpiod_line *alarm)
{
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(2);
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    if (wait_for_level(echo, 0, TIMEOUT_US) < 0)
        return -1;
    if (wait_for_level(echo, 1, TIMEOUT_US) < 0)
        return -1;
    uint32_t start = gpiod_line_get_value(echo);
    if (start < 0) {
        fprintf(stderr, "Failed to read echo start: %s\n", strerror(errno));
        return -1;
    }
    if (wait_for_level(echo, 0, TIMEOUT_US) < 0)
        return -1;
    uint32_t elapsed = gpiod_line_get_value(echo);
    if (elapsed < 0) {
        fprintf(stderr, "Failed to read echo end: %s\n", strerror(errno));
        return -1;
    }
    return (int)((elapsed - start) * 58.0 / 1000.0);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL, *alarm = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    alarm = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!trigger || !echo || !alarm) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(alarm, "hc-sr04-alarm", 0) < 0) {
        fprintf(stderr, "Failed to request alarm line: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        int distance = measure_distance(trigger, echo, alarm);
        if (distance < 0) {
            fprintf(stderr, "Invalid reading, giving up.\n");
            break;
        }
        if (distance > 1000) {
            printf("Distance: %d mm\n", distance);
        } else {
            printf("Distance: %d mm\n", distance);
        }
        fflush(stdout);
        usleep(LOOP_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (alarm) gpiod_line_release(alarm);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output on GPIO %d (BCM) is now %s\n",
           GPIO_LINE, (gpiod_line_get_value(line) == 0) ? "LOW" : "HIGH");

    /* Main loop: toggle every POLL_INTERVAL_SEC seconds */
    while (keep_running) {
        ret = gpiod_line_set_value(line, !gpiod_line_get_value(line));
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("State: %s\n", (gpiod_line_get_value(line) == 0) ? "LOW" : "HIGH");
        sleep(POLL_INTERVAL_SEC);
    }

    /* Clean up: set to LOW and release line */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_18 18
#define GPIO_24 24
#define CONSUMER "gpio_test"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line18 = NULL;
static struct gpiod_line *line24 = NULL;

static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(18)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line24) {
        perror("gpiod_chip_get_line(24)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(18)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line24, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(24)");
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO 18 and GPIO 24 initialized to LOW.\n");
    printf("Press Ctrl+C to exit.\n");

    while (keep_running) {
        if (gpiod_line_set_value(line18, 1) < 0) {
            perror("gpiod_line_set_value(18)");
            break;
        }
        if (gpiod_line_set_value(line24, 0) < 0) {
            perror("gpiod_line_set_value(24)");
            break;
        }
        printf("GPIO 18 HIGH, GPIO 24 LOW\n");
        sleep(1);

        if (gpiod_line_set_value(line18, 0) < 0) {
            perror("gpiod_line_set_value(18)");
            break;
        }
        if (gpiod_line_set_value(line24, 1) < 0) {
            perror("gpiod_line_set_value(24)");
            break;
        }
        printf("GPIO 18 LOW, GPIO 24 HIGH\n");
        sleep(1);
    }

    gpiod_line_set_value(line18, 0);
    gpiod_line_set_value(line24, 0);
    gpiod_line_release(line18);
    gpiod_line_release(line24);
    gpiod_chip_close(chip);

    printf("GPIO lines released. Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_1 2
#define GPIO_2 3
#define GPIO_3 23
#define CONSUMER "digital_output"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_line *line3 = NULL;

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

void cleanup(void) {
    if (line1) {
        gpiod_line_release(line1);
        line1 = NULL;
    }
    if (line2) {
        gpiod_line_release(line2);
        line2 = NULL;
    }
    if (line3) {
        gpiod_line_release(line3);
        line3 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_1);
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output line1");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output line2");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line3, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output line3");
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        printf("GPIO 1: %d, GPIO 2: %d, GPIO 3: %d\n",
               gpiod_line_get_value(line1),
               gpiod_line_get_value(line2),
               gpiod_line_get_value(line3));
        fflush(stdout);
        sleep(2);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#include <mqtt/mqtt.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "raspberry_pi_sensor"
#define MQTT_TOPIC "sensor_data"
#define READ_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int *value) {
    static const char *error_msg = "Error reading sensor data";
    *value = 42;
    return 0;
}

int main(void) {
    int rc;
    struct timespec sleep_time = {READ_INTERVAL_SEC, 0};

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize MQTT */
    mqtt_lib_t lib;
    rc = mqtt_lib_create(&lib);
    if (rc != MQTT_SUCCESS) {
        fprintf(stderr, "MQTT library initialisation failed: %s\n", mqtt_strerror(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = mqtt_lib_connect_async(lib, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (rc != MQTT_SUCCESS) {
        fprintf(stderr, "MQTT connect failed: %s\n", mqtt_strerror(rc));
        mqtt_lib_destroy(&lib);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Wait for connect to complete */
    while (running) {
        rc = mqtt_lib_wait_connect(lib);
        if (rc == MQTT_SUCCESS) {
            break;
        }
        if (rc == MQTT_CONNACK_REFUSED) {
            fprintf(stderr, "MQTT broker refused connection\n");
        } else if (rc == MQTT_CONNACK_SERVER_CLOSED) {
            fprintf(stderr, "MQTT broker closed connection\n");
        } else {
            fprintf(stderr, "MQTT connect error: %s\n", mqtt_strerror(rc));
        }
        gpioDelay(100000); /* 100 ms */
    }

    if (!running) {
        /* If we exited before connect, we need to tear down */
        mqtt_lib_destroy(&lib);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Wait for a valid client token to be returned */
    while (running) {
        rc = mqtt_lib_wait_client_token(lib);
        if (rc == MQTT_SUCCESS) {
            break;
        }
        if (rc == MQTT_CONNACK_SERVER_CLOSED) {
            fprintf(stderr, "MQTT broker closed connection\n");
        } else if (rc == MQTT_CONNACK_REFUSED) {
            fprintf(stderr, "MQTT broker refused connection\n");
        } else {
            fprintf(stderr, "MQTT client token error: %s\n", mqtt_strerror(rc));
        }
        gpioDelay(100000);
    }

    if (!running) {
        /* If we exited before token, we need to tear down */
        mqtt_lib_destroy(&lib);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Wait for a valid topic subscribe to be returned */
    while (running) {
        rc = mqtt_lib_wait_topic_subscribe(lib, MQTT_TOPIC, 1);
        if (rc == MQTT_SUCCESS) {
            break;
        }
        if (rc == MQTT_CONNACK_SERVER_CLOSED) {
            fprintf(stderr, "MQTT broker closed connection\n");
        } else if (rc == MQTT_CONNACK_REFUSED) {
            fprintf(stderr, "MQTT broker refused connection\n");
        } else {
            fprintf(stderr, "MQTT topic subscribe error: %s\n", mqtt_strerror(rc));
        }
        gpioDelay(100000);
    }

    if (!running) {
        /* If we exited before token, we need to tear down */
        mqtt_lib_destroy(&lib);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Publish loop */
    while (running) {
        int sensor_value = 0;
        if (read_sensor(&sensor_value) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
        } else {
            char payload[32];
            snprintf(payload, sizeof(payload), "%d", sensor_value);

            MQTTClient client;
            MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60, NULL);
            if (!client.state) {
                fprintf(stderr, "MQTT client creation failed\n");
                MQTTClient_destroy(&client);
                continue;
            }

            rc = MQTTClient_publish(client, NULL, MQTT_TOPIC, payload, strlen(payload), 0);
            if (rc != MQTT_SUCCESS) {
                fprintf(stderr, "MQTT publish failed: %s\n", mqtt_strerror(rc));
            } else {
                printf("Published: %s\n", payload);
            }

            MQTTClient_destroy(&client);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown */
    MQTTClient_destroy(&lib);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    while (running) {
        if (gpioPWM(PWM_PIN, 500) != 0) {
            fprintf(stderr, "Error: gpioPWM failed\n");
            break;
        }
        printf("PWM value: 500\n");
        fflush(stdout);
        sleep(5);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_TRIGGER 23
#define GPIO_ECHO_1 24
#define GPIO_ECHO_2 24
#define TIMEOUT_US 1000000
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int val, uint32_t timeout_us) {
    uint32_t start = (uint32_t)clock();
    while (1) {
        int v = gpiod_line_get_value(line);
        if (v < 0) {
            return -1;
        }
        if (v == val) return 0;
        if ((uint32_t)(clock() - start) >= timeout_us) return -2;
    }
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo1, struct gpiod_line *echo2) {
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;

    int timeout = 0;
    int got1 = 0, got2 = 0;
    while (timeout < TIMEOUT_US) {
        int v1 = wait_for_level(echo1, 0, timeout_us);
        if (v1 < 0) return -1;
        if (v1 == 0) { got1 = 1; timeout = 0; }
        int v2 = wait_for_level(echo2, 0, timeout_us);
        if (v2 < 0) return -1;
        if (v2 == 0) { got2 = 1; timeout = 0; }
    }
    if (!got1 || !got2) return -1;

    uint32_t t0 = (uint32_t)clock();
    while (gpiod_line_get_value(echo1) == 1) {
        if ((uint32_t)(clock() - t0) >= TIMEOUT_US) return -1;
    }
    uint32_t t1 = (uint32_t)clock();
    while (gpiod_line_get_value(echo2) == 1) {
        if ((uint32_t)(clock() - t1) >= TIMEOUT_US) return -1;
    }
    uint32_t t2 = (uint32_t)clock();
    return (int)((t2 - t1) + (t1 - t0));
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, GPIO_TRIGGER);
    struct gpiod_line *echo1 = gpiod_chip_get_line(chip, GPIO_ECHO_1);
    struct gpiod_line *echo2 = gpiod_chip_get_line(chip, GPIO_ECHO_2);
    if (!trig || !echo1 || !echo2) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(echo1, "hc-sr04-echo1") < 0) {
        fprintf(stderr, "Failed to request echo1 line: %s\n", strerror(errno));
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(echo2, "hc-sr04-echo2") < 0) {
        fprintf(stderr, "Failed to request echo2 line: %s\n", strerror(errno));
        gpiod_line_release(trig);
        gpiod_line_release(echo1);
        gpiod_chip_close(chip);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        int d = measure_distance(trig, echo1, echo2);
        if (d < 0) {
            fprintf(stderr, "Error measuring distance.\n");
        } else {
            printf("Distance: %d cm\n", d);
        }
        usleep(POLL_INTERVAL_US);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo1);
    gpiod_line_release(echo2);
    gpiod_chip_close(chip);
    printf("\nProgram terminated cleanly.\n");
    return 0;
}

