#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <mqtt.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_sensor_pub"
#define MQTT_TOPIC "sensor/readings"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define POLL_DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int publish_reading(int client_id, const char *topic, const char *payload) {
    MQTTClient *client = mqtt_client_new();
    if (!client) {
        fprintf(stderr, "Error: Failed to create MQTT client.\n");
        return -1;
    }

    int rc = mqtt_client_connect_async(client, client_id, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to connect to MQTT broker: %s\n", mqtt_strerror(rc));
        mqtt_client_destroy(client);
        return -1;
    }

    rc = mqtt_client_subscribe_async(client, NULL, topic, 1);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to subscribe to topic: %s\n", mqtt_strerror(rc));
        mqtt_client_disconnect(client);
        mqtt_client_destroy(client);
        return -1;
    }

    rc = mqtt_client_publish_async(client, NULL, topic, payload, strlen(payload), 0);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to publish to topic: %s\n", mqtt_strerror(rc));
        mqtt_client_unsubscribe(client, topic);
        mqtt_client_disconnect(client);
        mqtt_client_destroy(client);
        return -1;
    }

    mqtt_client_wait(client, 0);
    mqtt_client_disconnect(client);
    mqtt_client_destroy(client);
    return 0;
}

static int read_sensor(int handle) {
    int value = 0;
    if (write(handle, "read", 1) != 1) {
        fprintf(stderr, "Error: Failed to write to sensor: %s\n", strerror(errno));
        return -1;
    }
    if (read(handle, &value, 1) != 1) {
        fprintf(stderr, "Error: Failed to read from sensor: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    int handle = open("/dev/gpiochip0", O_RDWR);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open /dev/gpiochip0: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(handle, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO mode.\n");
        close(handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting sensor reading and MQTT publishing...\n");

    while (running) {
        int sensor_value = read_sensor(handle);
        if (sensor_value < 0) {
            fprintf(stderr, "Error: Failed to read sensor value.\n");
            gpioTerminate();
            return 1;
        }

        if (sensor_value == 0) {
            fprintf(stderr, "Warning: Sensor reading is zero, skipping publish.\n");
            gpioDelay(100000);
            continue;
        }

        char payload[32];
        snprintf(payload, sizeof(payload), "%d", sensor_value);

        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (publish_reading(MQTT_CLIENT_ID, MQTT_TOPIC, payload) == 0) {
                success = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                gpioDelay(RETRY_DELAY_MS * 1000);
            }
        }

        if (!success) {
            fprintf(stderr, "Error: Failed to publish reading after %d attempts.\n", MAX_RETRIES);
            gpioTerminate();
            return 1;
        }

        gpioDelay(POLL_DELAY_MS * 1000);
    }

    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18
#define POLL_INTERVAL_US 50000  /* 0.05 seconds */

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (line17 == NULL) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (line18 == NULL) {
        perror("gpiod_chip_get_line(18)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line17, "digital_out", 0) < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, "digital_out", 0) < 0) {
        perror("gpiod_line_request_output(18)");
        goto cleanup;
    }

    /* Main loop: toggle each line once per cycle */
    while (keep_running) {
        /* Toggle line 17 */
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("gpiod_line_set_value(17, HIGH)");
            goto cleanup;
        }
        usleep(POLL_INTERVAL_US);
        if (!keep_running) break;

        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("gpiod_line_set_value(17, LOW)");
            goto cleanup;
        }
        usleep(POLL_INTERVAL_US);

        /* Toggle line 18 */
        if (gpiod_line_set_value(line18, 1) < 0) {
            perror("gpiod_line_set_value(18, HIGH)");
            goto cleanup;
        }
        usleep(POLL_INTERVAL_US);
        if (!keep_running) break;

        if (gpiod_line_set_value(line18, 0) < 0) {
            perror("gpiod_line_set_value(18, LOW)");
            goto cleanup;
        }
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line17 != NULL) {
        gpiod_line_release(line17);
    }
    if (line18 != NULL) {
        gpiod_line_release(line18);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("GPIO 17: %s\n", gpiod_line_get_value(line17));
        printf("GPIO 18: %s\n", gpiod_line_get_value(line18));
    }

    return ret;
}

