#include <stdio.h>
#include <stdlib.h>
#include <termios.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>

#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE B921000

static int serial_fd = -1;

static void cleanup(int signum) {
    (void)signum;
    if (serial_fd >= 0) {
        close(serial_fd);
        serial_fd = -1;
    }
    _exit(0);
}

static int init_serial(const char *port, speed_t baud) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening serial port %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag = 0;
    tty.c_lflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    serial_fd = init_serial(SERIAL_PORT, BAUD_RATE);
    if (serial_fd < 0) {
        return 1;
    }

    char buffer[256];
    while (1) {
        ssize_t bytes_read = read(serial_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s\n", buffer);
            fflush(stdout);
        } else if (bytes_read == 0) {
            printf("No data available\n");
            fflush(stdout);
        } else {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
            break;
        }
    }

    if (serial_fd >= 0) {
        close(serial_fd);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

int main(void) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Wake up MPU6050 (clear sleep bit)
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error waking MPU6050: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(100000); // 100 ms

    // Verify device presence by reading a known register
    uint8_t reg = ACCEL_XOUT_H;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU6050 detected at address 0x%02X\n", MPU6050_ADDR);

    while (1) {
        uint8_t buf[6];
        // Read 6 bytes starting from ACCEL_XOUT_H
        if (write(fd, buf, 6) != 6) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        // Read 16-bit big-endian values
        int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Accel: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);

        usleep(100000); // 100 ms
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define READ_INTERVAL_SEC 5

static int i2c_fd = -1;

static int i2c_open(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing reg address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int bmp280_init(int fd) {
    if (i2c_write_reg8(fd, 0xF4, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xF5, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xF6, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xF7, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xF8, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xF9, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xFA, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xFB, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xFC, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xFD, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xFE, 0x00) < 0) return -1;
    return 0;
}

static int bmp280_read(int fd, int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    int16_t raw_temp, raw_press, raw_hum;
    if (i2c_read_reg16(fd, 0x00, &raw_temp) < 0) return -1;
    if (i2c_read_reg16(fd, 0x02, &raw_press) < 0) return -1;
    if (i2c_read_reg16(fd, 0x04, &raw_hum) < 0) return -1;
    *temperature = (int32_t)raw_temp;
    *pressure = (int32_t)((uint32_t)raw_press << 12) >> 12;
    *humidity = (int32_t)((uint32_t)raw_hum << 12) >> 12;
    return 0;
}

int main(void) {
    i2c_fd = i2c_open();
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }
    if (bmp280_init(i2c_fd) < 0) {
        fprintf(stderr, "BMP280 initialization failed.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    printf("BMP280 initialized at address 0x%02X on %s.\n", BMP280_I2C_ADDR, I2C_BUS);
    while (1) {
        int32_t t, p, h;
        if (bmp280_read(i2c_fd, &t, &p, &h) == 0) {
            printf("Temperature: %d C, Pressure: %d Pa, Humidity: %d %%\n", t, p, h);
        } else {
            fprintf(stderr, "Failed to read BMP280 data.\n");
        }
        sleep(READ_INTERVAL_SEC);
    }
    close(i2c_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 4

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (is pigpiod running?)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, 1000) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, 100) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, 50) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    printf("PWM output on GPIO %d (frequency 1 kHz, range 0-100) started.\n", PWM_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        gpioPWM(PWM_PIN, 50);
        gpioDelay(100000);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nPWM output stopped.\n");
    return EXIT_SUCCESS;
}

