#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#include <mqtt/mqtt.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "raspberry_pi_sensor"
#define MQTT_TOPIC "sensor_data"
#define READ_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int *value) {
    static int last_value = 0;
    static int delay_ms = 100;

    *value = last_value;
    gpioDelay(delay_ms * 1000);
    last_value = gpioRead(0);
    return 0;
}

int main(void) {
    int rc;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = mqtt_create(MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTT_CLIENT_ID, 65536, 10);
    if (rc != MQTT_SUCCESS) {
        fprintf(stderr, "MQTT client creation failed: %s\n", mqtt_strerror(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = mqtt_connect_async(rc, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, 10);
    if (rc != MQTT_SUCCESS) {
        fprintf(stderr, "MQTT connect failed: %s\n", mqtt_strerror(rc));
        mqtt_destroy(rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = mqtt_subscribe(rc, MQTT_TOPIC, 1);
    if (rc != MQTT_SUCCESS) {
        fprintf(stderr, "MQTT subscribe failed: %s\n", mqtt_strerror(rc));
        mqtt_destroy(rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Publishing sensor data to %s every %d seconds. Press Ctrl+C to exit.\n", MQTT_TOPIC, READ_INTERVAL_SEC);

    while (running) {
        int sensor_value;
        if (read_sensor(&sensor_value) != 0) {
            fprintf(stderr, "Error reading sensor value\n");
        } else {
            char payload[32];
            snprintf(payload, sizeof(payload), "%d", sensor_value);

            rc = mqtt_publish(rc, MQTT_TOPIC, payload, strlen(payload), 0, true);
            if (rc != MQTT_SUCCESS) {
                fprintf(stderr, "MQTT publish failed: %s\n", mqtt_strerror(rc));
            }
        }

        sleep(READ_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    mqtt_unsubscribe(rc, MQTT_TOPIC);
    mqtt_disconnect(rc, 1000);
    mqtt_destroy(rc);
    gpioTerminate();

    return EXIT_SUCCESS;
}

