    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line(GPIO_PIN_1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(GPIO_PIN_1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(GPIO_PIN_2)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 0.5 seconds */
    while (running) {
        int v1 = gpiod_line_get_value(line1);
        int v2 = gpiod_line_get_value(line2);

        if (v1 < 0 || v2 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, v1, GPIO_PIN_2, v2);
        fflush(stdout);

        /* Sleep 0.5 seconds, but wake early on signal */
        for (int i = 0; i < 5 && running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

