#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_18 18
#define GPIO_19 19
#define CONSUMER "digital_output"
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line18 = NULL;
    struct gpiod_line *line19 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(18)");
        goto cleanup;
    }

    line19 = gpiod_chip_get_line(chip, GPIO_19);
    if (!line19) {
        perror("gpiod_chip_get_line(19)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(18)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line19, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(19)");
        goto cleanup;
    }

    /* Main loop: toggle each line once per 0.5-second interval */
    while (running) {
        /* Toggle GPIO 18 */
        if (gpiod_line_set_value(line18, 1) < 0) {
            perror("gpiod_line_set_value(18, 1)");
            goto cleanup;
        }
        /* Wait 500 ms, checking for shutdown signal every 100 ms */
        for (int i = 0; i < 5 && running; i++) {
            usleep(100000);
        }
        if (!running) break;
        if (gpiod_line_set_value(line18, 0) < 0) {
            perror("gpiod_line_set_value(18, 0)");
            goto cleanup;
        }

        /* Toggle GPIO 19 */
        if (gpiod_line_set_value(line19, 1) < 0) {
            perror("gpiod_line_set_value(19, 1)");
            goto cleanup;
        }
        for (int i = 0; i < 5 && running; i++) {
            usleep(100000);
        }
        if (!running) break;
        if (gpiod_line_set_value(line19, 0) < 0) {
            perror("gpiod_line_set_value(19, 0)");
            goto cleanup;
        }

        /* Print the current state of both lines */
        printf("GPIO 18: %s, GPIO 19: %s\n",
               gpiod_line_get_value(line18),
               gpiod_line_get_value(line19));
        fflush(stdout);

        /* Wait 500 ms before next iteration */
        for (int i = 0; i < 5 && running; i++) {
            usleep(100000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line18) {
        gpiod_line_release(line18);
    }
    if (line19) {
        gpiod_line_release(line19);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <termios.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>

#define UART_PORT "/dev/ttyAMA0"
#define BAUD_RATE B921000

int main(void) {
    int fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART port %s: %s\n", UART_PORT, strerror(errno));
        return EXIT_FAILURE;
    }

    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("UART initialized on %s at %d baud. Waiting for data...\n", UART_PORT, BAUD_RATE);

    while (1) {
        int ch = getchar();
        if (ch == EOF) {
            if (errno == EAGAIN || errno == EINTR) {
                break;
            }
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            break;
        }
        printf("%c", ch);
    }

    close(fd);
    return EXIT_SUCCESS;
}

