#define CONSUMER "gpio_test"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line18 = NULL;
static struct gpiod_line *line23 = NULL;
static struct gpiod_line *line24 = NULL;

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static void cleanup(void) {
    if (line18) {
        gpiod_line_release(line18);
        line18 = NULL;
    }
    if (line23) {
        gpiod_line_release(line23);
        line23 = NULL;
    }
    if (line24) {
        gpiod_line_release(line24);
        line24 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line18 || !line23 || !line24) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO 18 as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line23, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO 23 as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line24, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO 24 as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("GPIO 18, 23, 24 initialized to LOW.\n");
    printf("Press Ctrl+C to exit.\n");

    while (keep_running) {
        int val18 = gpiod_line_get_value(line18);
        int val23 = gpiod_line_get_value(line23);
        int val24 = gpiod_line_get_value(line24);

        if (val18 < 0 || val23 < 0 || val24 < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        printf("GPIO 18: %d, GPIO 23: %d, GPIO 24: %d\n", val18, val23, val24);
        fflush(stdout);

        if (gpiod_line_set_value(line18, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO 18 high: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_set_value(line23, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO 23 high: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_set_value(line24, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO 24 high: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;

        }
        usleep(100000);
        if (gpiod_line_set_value(line18, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO 18 low: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_set_value(line23, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO 23 low: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_set_value(line24, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO 24 low: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;

        }
        usleep(100000);
    }

    printf("\nExiting...\n");
    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
