#define DHT22_PIN 4
#define CONSUMER "dht22-reader"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_line(struct gpiod_line *line, int val, int timeout_ms) {
    for (int i = 0; i < timeout_ms; i++) {
        if (gpiod_line_get_value(line) == val) return 0;
        usleep(1000);
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    if (gpiod_line_request_output(line, CONSUMER, 1) < 0) return -1;
    gpiod_line_set_value(line, 1);
    usleep(10000);
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(40);
    if (gpiod_line_request_input(line, CONSUMER) < 0) return -1;

    if (wait_for_line(line, 0, 100) < 0) return -1;
    if (wait_for_line(line, 1, 100) < 0) return -1;
    if (wait_for_line(line, 0, 100) < 0) return -1;

    unsigned char data[5] = {0};
    for (int i = 0; i < 40; i++) {
        if (wait_for_line(line, 1, 100) < 0) return -1;
        data[i / 8] <<= 1;
        if (gpiod_line_get_value(line) == 1) data[i / 8] |= 1;
        if (wait_for_line(line, 0, 100) < 0) return -1;
    }
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temp, hum;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
