#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#include <mqtt/mqtt.h>

#define MCP3008_CHANNEL 0
#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "sensor/mcp3008"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3-byte transfer, mode 0,0):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended mode + channel select)
     *   Byte 2: 0x00  (don't care, clocked out to read remaining data)
     *
     * Response:
     *   Byte 0: undefined
     *   Byte 1: bits 7..2 undefined, bit 1 = null bit, bit 0 = MSB of result
     *   Byte 2: bits 7..0 = result
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(0, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed: returned %d\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(0, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    MQTTClient client;
    int rc = MQTTClientCreate(&client, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, MQTT_CLIENT_KEEPALIVE_INTERVAL, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTTClientCreate failed: %s\n", MQTT_CLIENT_get_error_string(rc));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = MQTTClientSetCallback(client, NULL, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTTClientSetCallback failed: %s\n", MQTT_CLIENT_get_error_string(rc));
        MQTTClientDestroy(&client);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = MQTTClientConnect(client, "client_id", 60);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTTClientConnect failed: %s\n", MQTT_CLIENT_get_error_string(rc));
        MQTTClientDestroy(&client);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = MQTTClientPublish(client, NULL, MQTT_TOPIC, (int)MCP3008_CHANNEL, 10, NULL, 0);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTTClientPublish failed: %s\n", MQTT_CLIENT_get_error_string(rc));
        MQTTClientDisconnect(client, 1000);
        MQTTClientDestroy(&client);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Publishing MCP3008 channel %d to %s every 1 second. Press Ctrl+C to exit.\n",
           MCP3008_CHANNEL, MQTT_TOPIC);

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read MCP3008 channel %d\n", MCP3008_CHANNEL);
        } else {
            char payload[32];
            snprintf(payload, sizeof(payload), "%d", adc_value);
            rc = MQTTClientPublish(client, NULL, MQTT_TOPIC, (int)adc_value, 10, payload, strlen(payload));
            if (rc != MQTTCLIENT_SUCCESS) {
                fprintf(stderr, "MQTTClientPublish failed: %s\n", MQTT_CLIENT_get_error_string(rc));
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    MQTTClientPublish(client, NULL, MQTT_TOPIC, 0, 10, NULL, 0);
    MQTTClientDisconnect(client, 1000);
    MQTTClientDestroy(&client);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
