#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CAPTURE_INTERVAL_MS 1000

static int fd = -1;

static int init_camera(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;

    fd = open(DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE);
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE);
        close(fd);
        fd = -1;
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    if (buf.length < (unsigned int)(WIDTH * HEIGHT * 3 / 2)) {
        fprintf(stderr, "Buffer too small for %dx%d image\n", WIDTH, HEIGHT);
        close(fd);
        fd = -1;
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queueing buffer: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_buffer outbuf;
    memset(&outbuf, 0, sizeof(outbuf));
    outbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    outbuf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &outbuf) < 0) {
        fprintf(stderr, "Error draining buffer: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    return 0;
}

static int capture_image(void) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queueing buffer: %s\n", strerror(errno));
        return -1;
    }

    struct timespec ts = {0, 1000000000L};
    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error draining buffer: %s\n", strerror(errno));
        return -1;
    }

    char filename[256];
    snprintf(filename, sizeof(filename), "image_%04d.jpg", (int)time(NULL));

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fwrite(buf.data.pixel, 1, buf.bytesused, fp) != (size_t)buf.bytesused) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    printf("Image saved to %s\n", filename);
    return 0;
}

int main(void) {
    if (init_camera() != 0) {
        return EXIT_FAILURE;
    }

    printf("Capturing images... (Press Ctrl+C to stop)\n");

    while (1) {
        if (capture_image() != 0) {
            fprintf(stderr, "Error capturing image, exiting\n");
            break;
        }
        usleep(CAPTURE_INTERVAL_MS * 1000);
    }

    if (fd >= 0) {
        close(fd);
        fd = -1;
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

