static int i2c_write_byte(int fd, unsigned char byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int pcf8574_write_value(int fd, unsigned char value) {
    unsigned char buf[NUM_LEDS + 1];
    buf[0] = 0x00;
    for (int i = 0; i < NUM_LEDS; i++) {
        buf[1 + i] = (value >> i) & 0x01;
    }
    return i2c_write_byte(fd, buf[0]);
}

static void cleanup(void) {
    if (fd >= 0) {
        close(fd);
        fd = -1;
    }
}

