int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error: cannot get line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Request the line as output, initial value 0 */
    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        fprintf(stderr, "Error: cannot request line %d as output: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Main loop: toggle every 0.01 seconds */
    while (1) {
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error: failed to set line high: %s\n", strerror(errno));
            goto cleanup;
