        usleep(POLL_INTERVAL_US);

        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error: failed to set line low: %s\n", strerror(errno));
            goto cleanup;
        }
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure line is left low on exit */
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
