#include <gpiod.h>

#define GPIO_TRIGGER 17
#define GPIO_ECHO_1 18
#define CHIP_NAME "gpiochip0"
#define TIMEOUT_US 30000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static int wait_for_level(struct gpiod_line *line, int val, uint32_t timeout_us) {
    uint32_t start = (uint32_t)clock();
    while (1) {
        int v = gpiod_line_get_value(line);
        if (v < 0) {
            return -1;
        }
        if (v == val) return 0;
        if ((uint32_t)(clock() - start) >= timeout_us) return -2;
    }
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    if (wait_for_level(echo, 0, TIMEOUT_US) < 0) return -1;
    if (wait_for_level(echo, 1, TIMEOUT_US) < 0) return -1;
    uint32_t start = (uint32_t)clock();
    if (wait_for_level(echo, 0, TIMEOUT_US) < 0) return -1;
    uint32_t pulse_us = (uint32_t)(clock() - start);
    return (int)(pulse_us * 58.0 / 1000000.0);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo1 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, GPIO_TRIGGER);
    echo1 = gpiod_chip_get_line(chip, GPIO_ECHO_1);
    if (!trig || !echo1) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo1, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int dist = measure_distance(trig, echo1);
        if (dist < 0) {
            fprintf(stderr, "Error: GPIO read/write failed or timeout.\n");
            goto cleanup;
        }
        printf("Distance: %d cm\n", dist);
        fflush(stdout);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo1) gpiod_line_release(echo1);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

