static int set_capture_params(void)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;

    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    for (i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF[%d] failed: %s\n", i, strerror(errno));
            return -1;
        }
        if (buf.length < 100 || buf.index >= V4L2_BUF_TYPE_VIDEO_CAPTURE_MAX) {
            fprintf(stderr, "Buffer %d too small or invalid\n", i);
            return -1;
        }
    }
    return 0;
}

static int capture_image(unsigned char **image, size_t *image_size)
{
    struct v4l2_buffer buf;
    struct v4l2_requestbuffers req;
    unsigned int i;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &req) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    *image = (unsigned char *)malloc(buf.bytesused);
    if (*image == NULL) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
        return -1;
    }
    *image_size = buf.bytesused;
    return 0;
}

static int save_image(const unsigned char *image, size_t image_size)
{
    FILE *fp = fopen("image.jpg", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return -1;
    }
    size_t written = fwrite(image, 1, image_size, fp);
    if (written != image_size) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (fd >= 0) {
        if (xioctl(fd, VIDIOC_STREAMOFF, .stream_type = V4L2_STREAM_OFF) < 0) {
            fprintf(stderr, "Warning: VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
        }
        close(fd);
        fd = -1;
    }
}

int main(void)
{
    unsigned char *image = NULL;
    size_t image_size = 0;
    int ret = EXIT_SUCCESS;

    if (open_camera() < 0) {
        return EXIT_FAILURE;
    }

    if (set_capture_params() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        if (capture_image(&image, &image_size) < 0) {
            ret = EXIT_FAILURE;
            break;
        }
        if (save_image(image, image_size) < 0) {
            ret = EXIT_FAILURE;
            break;
        }
        usleep(CAPTURE_INTERVAL_US);
    }

    cleanup();
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    while (running) {
        if (gpioPWM(PWM_PIN, 500) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle\n");
            break;
        }
        printf("PWM duty cycle: 500\n");
        fflush(stdout);
        gpioDelay(5000000);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x27
#define NUM_LEDS 8

static int i2c_fd = -1;

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static int i2c_write_byte(uint8_t value) {
    if (i2c_fd < 0) return -1;
    if (write(i2c_fd, &value, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", PCF8574_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t init_cmd[2] = {0x00, 0x00};
    if (i2c_write_byte(init_cmd[0]) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(10000);

    uint8_t display_data[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++) {
        display_data[i] = (i < 8) ? i : 0xFF;
    }

    for (int i = 0; i < NUM_LEDS; i++) {
        if (i2c_write_byte(display_data[i]) < 0) {
            fprintf(stderr, "Failed to write to PCF8574 at column %d\n", i);
            cleanup();
            return EXIT_FAILURE;
        }
        usleep(10000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

