#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

int main(void) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Wake up MPU6050 (clear sleep bit)
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error waking MPU6050: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(100000); // 100 ms

    // Verify device presence by reading a known register
    uint8_t reg = ACCEL_XOUT_H;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU6050 detected at address 0x%02X\n", MPU6050_ADDR);

    while (1) {
        uint8_t buf[6];
        // Read 6 bytes starting from ACCEL_XOUT_H
        if (write(fd, buf, 6) != 6) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        // Read 16-bit big-endian values
        int16_t x = (buf[0] << 8) | buf[1];
        int16_t y = (buf[2] << 8) | buf[3];
        int16_t z = (buf[4] << 8) | buf[5];

        printf("Accel: X=%d, Y=%d, Z=%d\n", x, y, z);
        fflush(stdout);

        usleep(100000); // 100 ms
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
