#include <gpiod.h>

#define GPIO_1 2
#define GPIO_2 3
#define GPIO_3 17
#define NUM_CYCLES 3
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_chip_get_line(chip, GPIO_1);
    lines[1] = gpiod_chip_get_line(chip, GPIO_2);
    lines[2] = gpiod_chip_get_line(chip, GPIO_3);
    if (!lines[0] || !lines[1] || !lines[2]) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(lines[0], "digital_out", 0) < 0 ||
        gpiod_line_request_output(lines[1], "digital_out", 0) < 0 ||
        gpiod_line_request_output(lines[2], "digital_out", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        int val = (i % 2 == 0) ? 1 : 0;
        if (gpiod_line_set_value(lines[0], val) < 0 ||
            gpiod_line_set_value(lines[1], val) < 0 ||
            gpiod_line_set_value(lines[2], val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("Cycle %d: GPIO%d=%d, GPIO%d=%d, GPIO%d=%d\n",
               i, GPIO_1, val, GPIO_2, val, GPIO_3, val);
        fflush(stdout);
        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

