#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define SHT31_ADDR 0x44
#define I2C_DEV "/dev/i2c-1"
#define MEASURE_CMD_HIGH 0x2C
#define MEASURE_CMD_LOW 0x06
#define MEASURE_DELAY_MS 10
#define READ_DELAY_MS 10

static int i2c_fd = -1;

static int sht31_init(void) {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_DEV, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", SHT31_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int sht31_read(float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    if (write(i2c_fd, cmd, 2) != 2) {
        fprintf(stderr, "Error writing measurement command: %s\n", strerror(errno));
        return -1;
    }
    usleep(MEASURE_DELAY_MS * 1000);

    uint8_t buf[6];
    if (read(i2c_fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading measurement data: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw_temperature = (buf[0] << 8) | buf[1];
    uint16_t raw_humidity = (buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)raw_temperature / 65535.0f;
    *humidity = 100.0f * (float)raw_humidity / 65535.0f;

    if (*temperature < -40.0f || *temperature > 125.0f || *humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Invalid reading: temperature=%.1f, humidity=%.1f\n", *temperature, *humidity);
        return -1;
    }
    return 0;
}

int main(void) {
    if (sht31_init() != 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        float temperature, humidity;
        if (sht31_read(&temperature, &humidity) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read SHT31 sensor.\n");
        }
        sleep(5);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return EXIT_SUCCESS;
}

