#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two GPIO lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_PIN_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line1, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_PIN_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }

    /* Main loop: toggle both lines once per second */
    while (keep_running) {
        /* Set both lines to the current state */
        if (gpiod_line_set_value(line1, 0) < 0) {
            fprintf(stderr, "Failed to set line %d: %s\n", GPIO_PIN_1, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            fprintf(stderr, "Failed to set line %d: %s\n", GPIO_PIN_2, strerror(errno));
            goto cleanup;
        }

        /* Wait for 1 second, checking for shutdown signal every 100 ms */
        for (int i = 0; i < POLL_INTERVAL_SEC * 10 && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("GPIO 2: %d, GPIO 3: %d\n", gpiod_line_get_value(line1), gpiod_line_get_value(line2));
    } else {
        fprintf(stderr, "Program terminated with errors.\n");
    }

    return ret;
}

