    ret = gpiod_line_request_output(line3, "digital_output", 0);
    if (ret < 0) { perror("gpiod_line_request_output line3"); goto cleanup; }
    ret = gpiod_line_request_output(line17, "digital_output", 0);
    if (ret < 0) { perror("gpiod_line_request_output line17"); goto cleanup; }

