    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(18)");
        goto cleanup;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        perror("gpiod_chip_get_line(27)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(18)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line27, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(27)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 0.01 seconds */
    while (keep_running) {
        int v18 = gpiod_line_get_value(line18);
        int v27 = gpiod_line_get_value(line27);

        if (v18 < 0 || v27 < 0) {
            fprintf(stderr, "Error reading GPIO lines: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("GPIO 18: %d, GPIO 27: %d\n", v18, v27);
        fflush(stdout);

        /* Sleep 0.01 seconds using nanosleep for portability */
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 100000000L };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && keep_running) {
            /* Interrupted by signal; check keep_running */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line18) {
        gpiod_line_release(line18);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

