#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define ECHO_PIN2   24

#define TIMEOUT_US  2000000  /* 2 s timeout for echo */
#define POLL_US     10000    /* 10 ms poll interval */
#define LOOP_US     100000   /* 100 ms between reports */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int wait_for_level(struct gpiod_line *line, int val, uint32_t timeout_us)
{
    uint32_t start = gpiod_line_get_value(line);
    if (start < 0) {
        fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
        return -1;
    }
    uint32_t elapsed = 0;
    while (elapsed < timeout_us) {
        start = gpiod_line_get_value(line);
        if (start < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (start == val)
            return 0;
        usleep(POLL_US);
        elapsed += POLL_US;
    }
    return -1;
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo1,
                            struct gpiod_line *echo2)
{
    /* Ensure trigger is low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for echo to go high */
    if (wait_for_level(echo1, 1, TIMEOUT_US) < 0)
        return -1;

    uint32_t start = gpiod_line_get_value(echo1);
    if (start < 0) {
        fprintf(stderr, "Failed to read echo start: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for echo to go low */
    if (wait_for_level(echo2, 0, TIMEOUT_US) < 0)
        return -1;

    uint32_t end = gpiod_line_get_value(echo2);
    if (end < 0) {
        fprintf(stderr, "Failed to read echo end: %s\n", strerror(errno));
        return -1;
    }

    uint32_t pulse_us = end - start;
    return (int)(pulse_us * 1000.0 / 2.0);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo1 = NULL, *echo2 = NULL;
    int ret = EXIT_FAILURE;

    /* Open the default gpiochip (gpiochip0 on Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo1 = gpiod_chip_get_line(chip, ECHO_PIN);
    echo2 = gpiod_chip_get_line(chip, ECHO_PIN2);
    if (!trig || !echo1 || !echo2) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request lines as outputs, initial value low */
    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(echo1, "hc-sr04-echo1", 0) < 0) {
        fprintf(stderr, "Failed to request echo1 line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(echo2, "hc-sr04-echo2", 0) < 0) {
        fprintf(stderr, "Failed to request echo2 line: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
