static int set_pwm(int pin, int duty_percent)
{
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int duty_us = (duty_percent * PWM_RANGE) / 100;
    if (gpioPWM(pin, duty_us) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure all three pins as hardware-PWM outputs */
    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range for all three pins */
    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) < 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure all PWMs start at 0 duty */
    if (set_pwm(PWM_PIN_1, 0) < 0 ||
        set_pwm(PWM_PIN_2, 0) < 0 ||
        set_pwm(PWM_PIN_3, 0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM control running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int duty1 = (rand() % 101) / 10;
        int duty2 = (rand() % 101) / 10;
        int duty3 = (rand() % 101) / 10;

        if (set_pwm(PWM_PIN_1, duty1) < 0 ||
            set_pwm(PWM_PIN_2, duty2) < 0 ||
            set_pwm(PWM_PIN_3, duty3) < 0) {
