        fprintf(stderr, "Failed to request line as input: %s\n", strerror(errno));
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                     (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > DHT_TIMEOUT_US) {
            fprintf(stderr, "DHT22 timeout: no response from device.\n");
            return -1;
