            if (bit_idx == 0) {
                if (last_state == 0) {
                    data[byte_idx] |= (1 << bit_idx);
                }
                last_state = 0;
            } else {
                if (last_state == 1) {
                    data[byte_idx] |= (1 << bit_idx);
                }
                last_state = 1;
            }
            bit_idx++;
            if (bit_idx == 8) {
                byte_idx++;
                bit_idx = 0;
                if (byte_idx == 4) {
                    if (data[4] == 0xFF) {
                        *hum = ((float)data[0] + (float)data[1]) / 10.0;
                        *temp = ((float)data[2] + (float)data[3]) / 10.0;
                        if (*temp < 0 || *temp > 125 || *hum < 0 || *hum > 100) {
                            fprintf(stderr, "Invalid DHT22 data: temp=%.1f, hum=%.1f\n", *temp, *hum);
                            return -1;
                        }
                        return 0;
                    } else {
