#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN_1 4
#define DHT22_PIN_2 17
#define NUM_READINGS 3
#define INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(struct gpiod_line *line1, struct gpiod_line *line2, int *out_temp, int *out_hum) {
    /*
     * DHT22 bit-banging sequence (32-bit transfer, 4000 us total)
     * line1: data, line2: clock
     * Returns 0 on success, -1 on timeout/error.
     */
    int data = 0;
    int i;

    /* Start signal: pull low for >=1 ms, then high */
    if (gpiod_line_request_output(line1, "dht22", 0) < 0) return -1;
    if (gpiod_line_request_output(line2, "dht22", 0) < 0) return -1;
    usleep(2000);
    gpiod_line_set_value(line1, 1);
    usleep(40);
    gpiod_line_set_value(line1, 0);
    usleep(40);
    gpiod_line_set_value(line1, 1);
    usleep(30);

    /* Switch to input for clock */
    if (gpiod_line_request_input(line2, "dht22") < 0) return -1;

    /* Clock out 80 bits */
    for (i = 0; i < 80; i++) {
        /* Low pulse ~50 us */
        gpiod_line_set_value(line1, 0);
        usleep(50);
        /* High pulse ~60 us */
        gpiod_line_set_value(line1, 1);
        usleep(60);

        /* Read clock low pulse: if high, data is 1 */
        int clock = gpiod_line_get_value(line2);
        if (clock < 0) return -1;
        if (clock == 1) {
            data |= (1 << (7 - i));
        }
    }

    /* Verify 40-bit CRC */
    if ((data >> 4) == (data & 0x0F) && (data << 4) == (data >> 4)) {
        *out_temp = (data >> 8) & 0x7F;
        *out_hum = data & 0x7F;
        return 0;
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, DHT22_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 4)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, DHT22_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 17)");
        goto cleanup;
    }

    /* Request lines as outputs for start, then inputs for clock */
    if (gpiod_line_request_output(line1, "dht22", 0) < 0) {
        perror("gpiod_line_request_output (start)");
        goto cleanup;
    }
    if (gpiod_line_request_input(line2, "dht22") < 0) {
        perror("gpiod_line_request_input (clock)");
        goto cleanup;
    }

    printf("DHT22 sensor interface started. Press Ctrl+C to exit.\n");

    for (int i = 0; i < NUM_READINGS && running; i++) {
        int temp, hum;
        int rc = read_dht22(line1, line2, &temp, &hum);
        if (rc == 0) {
            printf("Reading %d: Temperature = %d C, Humidity = %d %%\n", i + 1, temp, hum);
        } else {
            fprintf(stderr, "Warning: DHT22 read failed (rc=%d)\n", rc);
        }
        sleep(INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

