#include <gpiod.h>

#define GPIO_16 16
#define GPIO_20 20
#define CONSUMER "digital_output"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line16 = NULL, *line20 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line16 = gpiod_chip_get_line(chip, GPIO_16);
    line20 = gpiod_chip_get_line(chip, GPIO_20);
    if (!line16 || !line20) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line16, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line16)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line20, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line20)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 0.1 seconds */
    while (keep_running) {
        int v16 = gpiod_line_get_value(line16);
        int v20 = gpiod_line_get_value(line20);

        if (v16 < 0 || v20 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        printf("GPIO 16: %d, GPIO 20: %d\n", v16, v20);
        fflush(stdout);

        /* Sleep 0.1 seconds, but wake early on signal */
        for (int i = 0; i < 10 && keep_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line16) gpiod_line_release(line16);
    if (line20) gpiod_line_release(line20);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <string.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

static int spi_fd = -1;

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_max31855(uint32_t *raw_value) {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};

    if (spi_transfer(tx, rx, sizeof(tx)) < 0) {
        return -1;
    }

    *raw_value = ((uint32_t)rx[0] << 24) | ((uint32_t)rx[1] << 16) |
                  ((uint32_t)rx[2] << 8) | (uint32_t)rx[3];

    return 0;
}

int main(void) {
    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    uint32_t raw_value;
    while (1) {
        if (read_max31855(&raw_value) < 0) {
            fprintf(stderr, "Error reading MAX31855. Exiting.\n");
            close(spi_fd);
            return EXIT_FAILURE;
        }

        printf("Raw Value: 0x%08X\n", raw_value);
        fflush(stdout);

        usleep(100000);
    }

    close(spi_fd);
    return EXIT_SUCCESS;
}

