#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define ECHO_PIN2   18
#define ECHO_PIN3   27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int val, int timeout_ms) {
    for (int i = 0; i < timeout_ms; i++) {
        int v = gpiod_line_get_value(line);
        if (v < 0) {
            fprintf(stderr, "wait_for_level: read error: %s\n", strerror(errno));
            return -1;
        }
        if (v == val) return 0;
        usleep(1000);
    }
    return -1;
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo1, struct gpiod_line *echo2, struct gpiod_line *echo3) {
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;

    int start = 1;
    int elapsed = 0;
    while (running) {
        int v = gpiod_line_get_value(echo1);
        if (v < 0) return -1;
        if (v == 1) {
            start = 0;
            elapsed = 0;
        } else if (v == 0) {
            elapsed++;
        } else {
            return -1;
        }
        usleep(1000);
        if (elapsed >= 200000) return -1;
    }

    elapsed = 0;
    while (running) {
        int v = gpiod_line_get_value(echo2);
        if (v < 0) return -1;
        if (v == 1) {
            elapsed = 0;
        } else if (v == 0) {
            elapsed++;
        } else {
            return -1;
        }
        usleep(1000);
        if (elapsed >= 200000) return -1;
    }

    elapsed = 0;
    while (running) {
        int v = gpiod_line_get_value(echo3);
        if (v < 0) return -1;
        if (v == 1) {
            elapsed = 0;
        } else if (v == 0) {
            elapsed++;
        } else {
            return -1;
        }
        usleep(1000);
        if (elapsed >= 200000) return -1;
    }

    return (int)((elapsed * 58.0) / 1000000.0);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo1 = NULL, *echo2 = NULL, *echo3 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo1 = gpiod_chip_get_line(chip, ECHO_PIN);
    echo2 = gpiod_chip_get_line(chip, ECHO_PIN2);
    echo3 = gpiod_chip_get_line(chip, ECHO_PIN3);
    if (!trig || !echo1 || !echo2 || !echo3) {
        fprintf(stderr, "gpiod_chip_get_line: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0 ||
        gpiod_line_request_input(echo1, "hc-sr04-echo1") < 0 ||
        gpiod_line_request_input(echo2, "hc-sr04-echo2") < 0 ||
        gpiod_line_request_input(echo3, "hc-sr04-echo3") < 0) {
        fprintf(stderr, "gpiod_line_request: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        int d = measure_distance(trig, echo1, echo2, echo3);
        if (d >= 0) {
            printf("Distance: %d cm\n", d);
        } else {
            printf("No response from HC-SR04\n");
        }
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo1) gpiod_line_release(echo1);
    if (echo2) gpiod_line_release(echo2);
    if (echo3) gpiod_line_release(echo3);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

