    if (line23) { gpiod_line_release(line23); line23 = NULL; }
    if (line24) { gpiod_line_release(line24); line24 = NULL; }
    if (chip) { gpiod_chip_close(chip); chip = NULL; }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line22 = gpiod_chip_get_line(chip, GPIO_22);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line17 || !line22 || !line23 || !line24) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line17, "digital_output", 0) < 0 ||
        gpiod_line_request_output(line22, "digital_output", 0) < 0 ||
        gpiod_line_request_output(line23, "digital_output", 0) < 0 ||
        gpiod_line_request_output(line24, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Digital output on GPIO 17, 22, 23, 24 (BCM). Press Ctrl+C to exit.\n");

    while (keep_running) {
        gpiod_line_set_value(line17, 1);
        gpiod_line_set_value(line22, 1);
        gpiod_line_set_value(line23, 1);
        gpiod_line_set_value(line24, 1);
        printf("GPIO 17: ON, GPIO 22: ON, GPIO 23: ON, GPIO 24: ON\n");
        fflush(stdout);

        gpiod_line_set_value(line17, 0);
        gpiod_line_set_value(line22, 0);
        gpiod_line_set_value(line23, 0);
        gpiod_line_set_value(line24, 0);
        printf("GPIO 17: OFF, GPIO 22: OFF, GPIO 23: OFF, GPIO 24: OFF\n");
        fflush(stdout);

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

