#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define CONSUMER "digital_output"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Request the line as output, initial value LOW */
    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Set the output value */
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO line %d HIGH: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Wait for a short interval to let the output settle */
    usleep(100000);

    /* Report the current state */
    printf("GPIO %d is currently %s\n", GPIO_LINE, (gpiod_line_get_value(line) == 1) ? "HIGH" : "LOW");
    fflush(stdout);

    /* Wait for a short interval to let the output settle */
    usleep(100000);

    ret = EXIT_SUCCESS;

cleanup:
    /* Release the line and close the chip on all exit paths */
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7
#define BME280_REG_CALIB00 0x88
#define BME280_REG_CALIB26 0xE1

static int i2c_fd = -1;

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read burst from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bme280_init(void) {
    uint8_t id;
    if (i2c_read_reg(BME280_REG_ID, &id) < 0) return -1;
    if (id != 0x60) {
        fprintf(stderr, "BME280 not found (ID=0x%02X, expected 0x60)\n", id);
        return -1;
    }

    if (i2c_write_reg(BME280_REG_RESET, 0xB6) < 0) return -1;
    usleep(2000);

    uint8_t ctrl_hum;
    if (i2c_read_reg(BME280_REG_CTRL_HUM, &ctrl_hum) < 0) return -1;
    if (ctrl_hum & 0x01) {
        i2c_write_reg(BME280_REG_CTRL_HUM, 0x01);
    }

    if (i2c_write_reg(BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg(BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;

    return 0;
}

static int bme280_read_calibration(void) {
    uint8_t cal[26];
    if (i2c_read_burst(BME280_REG_CALIB00, cal, 26) < 0) return -1;
    memcpy(&cal[12], cal, 24);

    uint8_t cal2[7];
    if (i2c_read_burst(BME280_REG_CALIB26, cal2, 7) < 0) return -1;
    memcpy(cal2, cal2 + 3, 4);

    return 0;
}

static int bme280_read_raw(int32_t *temp, int32_t *press, int32_t *hum) {
    uint8_t data[8];
    if (i2c_read_burst(BME280_REG_DATA, data, 8) < 0) return -1;

    *press = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
    *temp = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));
    *hum = (int32_t)((data[6] << 8) | data[7]);
    return 0;
}

static int bme280_compensate(int32_t raw_t, int32_t raw_p, int32_t raw_h,
                            double *t_fine, double *p_fine) {
    double v1 = ((double)raw_t / 16384.0 - (double)0.5) * 1048576.0;
    double v2 = ((double)raw_t / 131072.0 - (double)0.5) * 1048576.0 * 16384.0;
    double v3 = v1 * v2;
    double t_fine_val = v3;

    v1 = ((double)raw_p / 134.0 - (double)0.5) * 1048576.0;
    v2 = ((double)raw_p / 131072.0 - (double)0.5) * 1048576.0 * 16384.0;
    v3 = v1 * v2;
    double p_fine_val = v3;

    v1 = ((double)raw_h / 16384.0 - (double)0.5) * 1048576.0;
    v2 = ((double)raw_h / 134.0 - (double)0.5) * 1048576.0 * 16384.0;
    v3 = v1 * v2;
    double h_val = v3;

    *t_fine = t_fine_val;
    *p_fine = p_fine_val;
    return 0;
}

int main(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bme280_init() < 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    if (bme280_read_calibration() < 0) {
        fprintf(stderr, "BME280 calibration read failed\n");
        close(i2c_fd);
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        int32_t raw_t, raw_p, raw_h;
        double t_fine, p_fine;

        if (bme280_read_raw(&raw_t, &raw_p, &raw_h) < 0) {
            fprintf(stderr, "BME280 read failed: %s\n", strerror(errno));
            close(i2c_fd);
            return 1;
        }

        if (bme280_compensate(raw_t, raw_p, raw_h, &t_fine, &p_fine) < 0) {
            fprintf(stderr, "BME280 compensation failed\n");
            close(i2c_fd);
            return 1;
        }

        printf("Temperature: %.2f C, Pressure: %.2f hPa, Humidity: %.2f %%\n",
               t_fine, p_fine, 0.0);
        fflush(stdout);

        sleep(5);
    }

    close(i2c_fd);
    return 0;
}

#include <stdio.h>
