#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define POLL_TIMEOUT_MS 1000

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Request the line as output, initial value 0 */
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* Main loop: toggle the output every 1 second */
    while (1) {
        int value = 0;
        if (gpiod_line_set_value(line, value) < 0) {
            fprintf(stderr, "Failed to set GPIO line %d value: %s\n", GPIO_LINE, strerror(errno));
            goto cleanup;
        }

        printf("GPIO %d: %d\n", GPIO_LINE, value);
        fflush(stdout);

        /* Sleep for 1 second, but wake early on signal */
        for (int i = 0; i < 10 && !signal(SIGINT); i++) {
            usleep(100000);
        }
    }

cleanup:
    /* Ensure the line is left low before releasing */
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
