}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define VEML7700_ADDR 0x10
#define VEML7700_REG_CONF 0x00
#define VEML7700_REG_ALS 0x04
#define I2C_BUS "/dev/i2c-1"

static int i2c_fd = -1;

static int veml7700_init(int fd) {
    uint8_t buf[2];
    buf[0] = VEML7700_REG_CONF;
    buf[1] = 0x00;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);
    return 0;
}

static int veml7700_read_als(int fd, uint16_t *als) {
    uint8_t reg = VEML7700_REG_ALS;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting register pointer: %s\n", strerror(errno));
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading ALS data: %s\n", strerror(errno));
        return -1;
    }
    *als = (uint16_t)((data[0] << 8) | data[1]);
    return 0;
}

int main(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (veml7700_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }
    while (1) {
        uint16_t als;
        if (veml7700_read_als(i2c_fd, &als) < 0) {
            close(i2c_fd);
            return 1;
        }
        printf("ALS: %u\n", als);
        fflush(stdout);
        sleep(0.5);
    }
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <termios.h>

#define BAUD_RATE B921000
#define READ_LEN 16

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

static int init_serial(int *fd) {
    int fd_tmp = open("/dev/serial0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd_tmp < 0) {
        fprintf(stderr, "Error opening /dev/serial0: %s\n", strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd_tmp, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd_tmp);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd_tmp, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd_tmp);
        return -1;
    }

    close(fd_tmp);
    *fd = fd_tmp;
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handler() != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_serial(&fd) != 0) {
        fprintf(stderr, "Serial initialization failed.\n");
        return EXIT_FAILURE;
    }

    printf("Serial port initialized. Waiting for data...\n");

    while (g_running) {
        char buf[READ_LEN];
        ssize_t n = read(fd, buf, READ_LEN);

        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
            } else {
                fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
            }
            break;
        }

        if (n == 0) {
            fprintf(stderr, "Serial device disconnected.\n");
            break;
        }

        printf("Received: %s\n", buf);
        fflush(stdout);

        usleep(100000);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_TRIGGER 17
#define GPIO_ECHO_1 18
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

static long long elapsed_us(struct timespec *start, struct timespec *end) {
    return (long long)(end->tv_sec - start->tv_sec) * 1000000LL +
           (long long)(end->tv_nsec - start->tv_nsec) / 1000LL;
}

static int trigger_and_measure(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;

    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (elapsed_us(&start, &now) > TIMEOUT_US) return -1;
    }
    clock_gettime(CLOCK_MONOTONIC, &now);
    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (elapsed_us(&now, &start) > TIMEOUT_US) return -1;
    }
    clock_gettime(CLOCK_MONOTONIC, &now);
    return (now.tv_sec - start.tv_sec) * 1000000LL +
             (now.tv_nsec - start.tv_nsec) / 1000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa = {0};
    sa.sa_handler = handle_sig;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, GPIO_TRIGGER);
    echo = gpiod_chip_get_line(chip, GPIO_ECHO_1);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0 ||
        gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request");
        goto cleanup;
    }

    while (running) {
        long long pulse = trigger_and_measure(trig, echo);
        if (pulse < 0) {
            fprintf(stderr, "Error: Timeout or communication failure.\n");
            goto cleanup;
        }
        printf("Pulse: %lld us\n", pulse);
        fflush(stdout);
        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
