#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32

static int i2c_fd = -1;

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    if (i2c_write_byte(fd, ADXL345_POWER_CTL, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, ADXL345_DATA_FORMAT, 0x0B) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_adxl345(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, ADXL345_DATAX0, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

int main(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize ADXL345\n");
        close(i2c_fd);
        return 1;
    }
    while (1) {
        int16_t x, y, z;
        if (read_adxl345(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read ADXL345 data\n");
            break;
        }
        printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        usleep(100000);
    }
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 8
#define DELAY_SEC 0.05

static const unsigned int pins[NUM_PINS] = {4, 17, 18, 22, 23, 24, 25, 27};

static volatile sig_atomic_t keep_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int pins_requested = 0;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "digital_output", 0) < 0) {
            fprintf(stderr, "Failed to request output on line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        pins_requested++;
    }

    while (keep_running) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set line %u high: %s\n", pins[i], strerror(errno));
                goto cleanup;
            }
        }
        printf("GPIO 4, 17, 18, 22, 23, 24, 25, 27 -> HIGH\n");
        fflush(stdout);
        sleep(DELAY_SEC);

        for (int i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set line %u low: %s\n", pins[i], strerror(errno));
                goto cleanup;
            }
        }
        printf("GPIO 4, 17, 18, 22, 23, 24, 25, 27 -> LOW\n");
        fflush(stdout);
        sleep(DELAY_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < pins_requested; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

