#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_4 4
#define GPIO_17 17
#define NUM_CYCLES 5

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line4 = NULL;
static struct gpiod_line *line17 = NULL;

static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        perror("gpiod_chip_get_line(4)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line4, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output(4)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line17, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output(17)");
        gpiod_line_release(line4);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        if (gpiod_line_set_value(line4, 1) < 0) {
            perror("gpiod_line_set_value(4, 1)");
            cleanup_and_exit(1);
        }
        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("gpiod_line_set_value(17, 0)");
            cleanup_and_exit(1);
        }
        printf("Cycle %d: GPIO 4=1, GPIO 17=0\n", i);
        sleep(1);

        if (gpiod_line_set_value(line4, 0) < 0) {
            perror("gpiod_line_set_value(4, 0)");
            cleanup_and_exit(1);
        }
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("gpiod_line_set_value(17, 1)");
            cleanup_and_exit(1);
        }
        printf("Cycle %d: GPIO 4=0, GPIO 17=1\n", i);
        sleep(1);
    }

    gpiod_line_set_value(line4, 0);
    gpiod_line_set_value(line17, 0);
    gpiod_line_release(line4);
    gpiod_line_release(line17);
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_21 21
#define CONSUMER "digital_output"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line21 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }

    line21 = gpiod_chip_get_line(chip, GPIO_21);
    if (!line21) {
        perror("gpiod_chip_get_line(21)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line17, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line21, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(21)");
        goto cleanup;
    }

    /* Main loop: toggle both lines once per 0.1 s */
    while (keep_running) {
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("gpiod_line_set_value(17, 1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line21, 1) < 0) {
            perror("gpiod_line_set_value(21, 1)");
            goto cleanup;
        }
        usleep(100000); /* 100 ms = 0.1 s */

        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("gpiod_line_set_value(17, 0)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line21, 0) < 0) {
            perror("gpiod_line_set_value(21, 0)");
            goto cleanup;
        }
        usleep(100000); /* 100 ms = 0.1 s */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line21) {
        gpiod_line_release(line21);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("GPIO 17 and GPIO 21 toggled once per 0.1 s. Exiting.\n");
    } else {
        fprintf(stderr, "Program terminated with errors.\n");
    }

    return ret;
}

