#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 24
#define CONSUMER "digital_output"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("Digital output on GPIO %d (BCM) initialized to 0.\n", GPIO_LINE);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_LINE, strerror(errno));
            goto cleanup;
        }

        if (val == 1) {
            printf("GPIO %d: HIGH\n", GPIO_LINE);
        } else {
            printf("GPIO %d: LOW\n", GPIO_LINE);
        }
        fflush(stdout);

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_PINS 8
#define CONSUMER "digital_output"

static const unsigned int pins[NUM_PINS] = {0, 1, 2, 3, 4, 5, 12, 17};

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    /* Open the gpiochip that exposes the BCM pins on the Pi (gpiochip0). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: cannot open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line as an output. */
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error: cannot get line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Error: cannot request line %u as output: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Set each pin to a unique value. */
    for (int i = 0; i < NUM_PINS; i++) {
        values[i] = i % 2;
        if (gpiod_line_set_value(lines[i], values[i]) < 0) {
            fprintf(stderr, "Error: cannot set line %u to %d: %s\n",
                    pins[i], values[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Report the state. */
    printf("Output values: ");
    for (int i = 0; i < NUM_PINS; i++)
        printf("%d ", values[i]);
    printf("\n");
    fflush(stdout);

    /* Wait 1 second, then turn off all lines. */
    sleep(1);
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            (void)gpiod_line_set_value(lines[i], 0);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines in reverse order. */
    for (int i = NUM_PINS - 1; i >= 0; i--) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

