#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_27 27
#define CONSUMER "digital_output"
#define POLL_INTERVAL_US 200000  /* 0.2 seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line27 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        perror("gpiod_chip_get_line(27)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line17, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line27, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(27)");
        goto cleanup;
    }

    /* Main loop: toggle each line once per cycle */
    while (running) {
        /* State 0: GPIO 17 LOW, GPIO 27 LOW */
        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("gpiod_line_set_value(17, 0)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line27, 0) < 0) {
            perror("gpiod_line_set_value(27, 0)");
            goto cleanup;
        }
        printf("GPIO 17: %d, GPIO 27: %d\n", 0, 0);
        fflush(stdout);

        /* State 1: GPIO 17 HIGH, GPIO 27 LOW */
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("gpiod_line_set_value(17, 1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line27, 0) < 0) {
            perror("gpiod_line_set_value(27, 0)");
            goto cleanup;
        }
        printf("GPIO 17: %d, GPIO 27: %d\n", 1, 0);
        fflush(stdout);

        /* State 2: GPIO 17 LOW, GPIO 27 HIGH */
        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("gpiod_line_set_value(17, 0)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line27, 1) < 0) {
            perror("gpiod_line_set_value(27, 1)");
            goto cleanup;
        }
        printf("GPIO 17: %d, GPIO 27: %d\n", 0, 1);
        fflush(stdout);

        /* State 3: GPIO 17 HIGH, GPIO 27 HIGH */
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("gpiod_line_set_value(17, 1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line27, 1) < 0) {
            perror("gpiod_line_set_value(27, 1)");
            goto cleanup;
        }
        printf("GPIO 17: %d, GPIO 27: %d\n", 1, 1);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Program terminated cleanly.\n");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define ALARM_PIN   27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *alarm = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    alarm = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!trig || !echo || !alarm) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04", 0) < 0 ||
        gpiod_line_request_input(echo, "hcsr04") < 0 ||
        gpiod_line_request_output(alarm, "hcsr04", 0) < 0) {
        perror("gpiod_line_request");
        goto cleanup;
    }

    printf("HC-SR04 ready. Press Ctrl+C to exit.\n");

    while (running) {
        gpiod_line_set_value(trig, 0);
        usleep(2);
        gpiod_line_set_value(trig, 1);
        usleep(10);
        gpiod_line_set_value(trig, 0);

        int timeout = 0;
        while (gpiod_line_get_value(echo) == 0 && running) {
            usleep(1);
            timeout += 1;
            if (timeout > 1000) {
                fprintf(stderr, "Timeout waiting for echo high.\n");
                goto cleanup;
            }
        }
        if (!running) break;

        long start_tick = 0;
        while (gpiod_line_get_value(echo) == 1 && running) {
            usleep(1);
            start_tick += 1;
            if (start_tick > 100000) {
                fprintf(stderr, "Timeout waiting for echo low.\n");
                goto cleanup;
            }
        }
        if (!running) break;

        long end_tick = 0;
        while (gpiod_line_get_value(echo) == 0 && running) {
            usleep(1);
            end_tick += 1;
            if (end_tick > 100000) {
                fprintf(stderr, "Timeout waiting for echo high.\n");
                goto cleanup;
            }
        }
        if (!running) break;

        long pulse_width = end_tick - start_tick;
        float distance = (float)pulse_width * 0.0343 / 2.0;
        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        gpiod_line_set_value(alarm, 1);
        usleep(500000);
        gpiod_line_set_value(alarm, 0);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (alarm) gpiod_line_release(alarm);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 21
#define PWM_PIN_3 22

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, 1000) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_2, 1000) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_3, 1000) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN_1, 128) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_2, 128) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_3, 128) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM output started on GPIO 18, 21, 22. Press Ctrl+C to exit.\n");

    while (running) {
        gpioPWM(PWM_PIN_1, 128);
        gpioPWM(PWM_PIN_2, 128);
        gpioPWM(PWM_PIN_3, 128);
        gpioDelay(100000);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    printf("PWM output stopped.\n");
    return EXIT_SUCCESS;
}

