#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define ECHO_PIN2   18

#define TIMEOUT_US  2000000
#define POLL_US     10000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int val, uint32_t timeout_us)
{
    uint32_t start = (uint32_t)clock();
    while (1) {
        int v = gpiod_line_get_value(line);
        if (v < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (v == val)
            return 0;
        if ((uint32_t)(clock() - start) >= timeout_us)
            return -1;
    }
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }

    if (wait_for_level(echo, 0, TIMEOUT_US) < 0)
        return -1;

    if (wait_for_level(echo, 1, TIMEOUT_US) < 0)
        return -1;

    uint32_t start = (uint32_t)clock();
    if (wait_for_level(echo, 0, TIMEOUT_US) < 0)
        return -1;

    uint32_t duration = (uint32_t)(clock() - start);
    return (int)(duration * 1000000.0 / 2.0);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo1 = NULL, *echo2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo1 = gpiod_chip_get_line(chip, ECHO_PIN);
    echo2 = gpiod_chip_get_line(chip, ECHO_PIN2);
    if (!trig || !echo1 || !echo2) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo1, "hcsr04-echo1") < 0) {
        fprintf(stderr, "Failed to request echo1 line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo2, "hcsr04-echo2") < 0) {
        fprintf(stderr, "Failed to request echo2 line: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        int d = measure_distance(trig, echo1);
        if (d < 0) {
            fprintf(stderr, "Measurement failed; continuing.\n");
            usleep(POLL_US);
            continue;
        }
        printf("Distance: %d mm\n", d);
        usleep(POLL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo1) gpiod_line_release(echo1);
    if (echo2) gpiod_line_release(echo2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

