static int read_measurement(int fd, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[9];
    if (i2c_read_block(fd, 0xA8, buf, 9) < 0) return -1;
    *red = (buf[1] << 8) | buf[0];
    *green = (buf[3] << 8) | buf[2];
    *blue = (buf[5] << 8) | buf[4];
    return 0;
}

