#include <signal.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm_duty(int pin, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    if (gpioPWM(pin, duty_percent) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_pwm_duty(PWM_PIN_1, 50) != 0 ||
        set_pwm_duty(PWM_PIN_2, 50) != 0 ||
        set_pwm_duty(PWM_PIN_3, 50) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        printf("GPIO 1: %d%%, GPIO 2: %d%%, GPIO 3: %d%%\n",
               50, 50, 50);
        fflush(stdout);
        sleep(5);
    }

    /* Clean up: set duty to 0 on all pins */
    set_pwm_duty(PWM_PIN_1, 0);
    set_pwm_duty(PWM_PIN_2, 0);
    set_pwm_duty(PWM_PIN_3, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

