#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define ECHO_PIN2   24

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo1 = NULL, *echo2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo1 = gpiod_chip_get_line(chip, ECHO_PIN);
    echo2 = gpiod_chip_get_line(chip, ECHO_PIN2);
    if (!trig || !echo1 || !echo2) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_output(echo1, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output(echo1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(echo2, "hcsr04", 0) < 0) {
        perror("gpiod_line_request_output(echo2)");
        goto cleanup;
    }

    printf("HC-SR04 ready. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig,0)");
            goto cleanup;
        }
        usleep(2);
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig,1)");
            goto cleanup;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig,0)");
            goto cleanup;
        }

        usleep(100);

        int timeout = 0;
        while (gpiod_line_get_value(echo1) == 0) {
            if (++timeout > 1000) {
                fprintf(stderr, "Timeout waiting for echo start.\n");
                goto cleanup;
            }
            usleep(1);
        }
        long start_tick = 0;
        while (gpiod_line_get_value(echo1) == 1) {
            start_tick++;
            if (start_tick > 1000) {
                fprintf(stderr, "Timeout waiting for echo end.\n");
                goto cleanup;
            }
            usleep(1);
        }
        long end_tick = 0;
        while (gpiod_line_get_value(echo2) == 1) {
            end_tick++;
            if (end_tick > 1000) {
                fprintf(stderr, "Timeout waiting for echo end.\n");
                goto cleanup;
            }
            usleep(1);
        }
        long elapsed = end_tick - start_tick;
        float distance = (elapsed * 1e-3) / 58.0;
        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo1) gpiod_line_release(echo1);
    if (echo2) gpiod_line_release(echo2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 18
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value 0 */
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Main loop: poll the line for a valid reading */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }
        if (val == 0) {
            printf("GPIO %d: 0\n", GPIO_LINE);
            fflush(stdout);
            break;
        }
        /* val == 1 indicates a read failure; break loop to exit */
        break;
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release the line and close the chip on all exit paths */
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define DELAY_US 200000  /* 0.2 seconds in microseconds */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    /* Install SIGINT handler for clean shutdown on Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO 18 as PWM output */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure PWM is off at start */
    if (gpioPWM(PWM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main loop: toggle every 0.2 seconds */
    while (running) {
        if (gpioPWM(PWM_PIN, 1) != 0) {
            fprintf(stderr, "Failed to set PWM high on GPIO %d\n", PWM_PIN);
            break;
        }
        gpioDelay(DELAY_US);
        if (!running) break;

        if (gpioPWM(PWM_PIN, 0) != 0) {
            fprintf(stderr, "Failed to set PWM low on GPIO %d\n", PWM_PIN);
            break;
        }
        gpioDelay(DELAY_US);
    }

    /* Clean up: set PWM to 0 and terminate pigpio */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

