        perror("gpiod_line_request_output 18");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output initialized. GPIO 17=0, GPIO 18=0.\n");
    printf("Press Ctrl+C to exit.\n");

    while (keep_running) {
        if (gpiod_line_set_value(line17, 1) < 0) {
