#define ACCEL_XOUT_H 0x3B

static int i2c_fd = -1;

static int i2c_init(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int mpu6050_read_reg(uint8_t reg, uint8_t *val) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, val, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_read_burst(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading burst from 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

