#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define POLL_INTERVAL_US 600000  /* 0.6 seconds */

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "digital-out", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output on GPIO %d (BCM) is now HIGH.\n", GPIO_LINE);
    fflush(stdout);

    while (keep_running) {
        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && keep_running; i++) {
            usleep(10000);  /* 10 ms */
        }

        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        printf("GPIO %d: %d\n", GPIO_LINE, val);
        fflush(stdout);

        /* Sleep the remainder of the interval */
        for (int i = 0; i < 50 && keep_running; i++) {
            usleep(10000);
        }
    }

    /* Clean up: set output low and release line */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d released. Exiting.\n", GPIO_LINE);
    return EXIT_SUCCESS;
}
